/**
 * Read the one contractual profile assigned to a user.
 * Legacy TRB Basic remains readable until the controlled migration is run.
 */
function trb_portal_user_profile( $user = null ) {
	$user = $user ? $user : wp_get_current_user();

	if ( ! $user || ! $user->exists() ) {
		return false;
	}

	foreach ( trb_portal_profiles() as $key => $profile ) {
		$roles = array_merge( array( $profile['role'] ), isset( $profile['aliases'] ) ? (array) $profile['aliases'] : array() );
		if ( array_intersect( $roles, (array) $user->roles ) ) {
			return $key;
		}
	}

	if ( in_array( 'artisti_trb_basic', (array) $user->roles, true ) ) {
		return 'trb';
	}

	// These long-standing QA accounts predate the contractual role migration.
	// They must exercise the complete portal exactly like an approved TRB artist.
	if ( in_array( strtolower( (string) $user->user_email ), array( 'spotify2@trbrec.com', 'spotify3@trbrec.com', 'spotify4@trbrec.com' ), true ) ) {
		return 'trb';
	}

	return false;
}

function trb_portal_profile_label( $profile = null ) {
	$profile = $profile ? $profile : trb_portal_user_profile();
	$profiles = trb_portal_profiles();

	return isset( $profiles[ $profile ] ) ? $profiles[ $profile ]['label'] : '';
}

/**
 * The contractual profile and the brand under which it belongs are distinct.
 * DDS, DDB and DDB-TRB remain Digital Distribution Bundle; TRB is TRB rec.
 */
function trb_portal_profile_affiliation( $profile = null ) {
	$profile = $profile ? $profile : trb_portal_user_profile();

	return 'trb' === $profile ? 'TRB rec - Music Publishing' : 'Digital Distribution Bundle';
}

/** Keep brand assets portable when the canonical host changes. */
function trb_portal_logo_url() {
	return content_url( '/uploads/2023/08/Vector-TRB-rec-White.png' );
}

function trb_portal_allowed_profiles() {
	return array_keys( trb_portal_profiles() );
}

function trb_portal_user_can_access( $profiles, $user = null ) {
	$profiles = is_array( $profiles ) ? $profiles : array( $profiles );
	$profiles = array_filter( array_map( 'sanitize_key', $profiles ) );

	if ( current_user_can( 'manage_options' ) ) {
		return true;
	}

	$user_profile = trb_portal_user_profile( $user );
	if ( 'ddb12' === $user_profile && in_array( 'ddb', $profiles, true ) ) {
		return true;
	}

	return in_array( $user_profile, $profiles, true );
}

/** Create the definitive DDB12 role with the same base permissions as DDB. */
function trb_portal_register_ddb12_role() {
	if ( get_role( 'artista_ddb12' ) ) {
		return;
	}

	$ddb  = get_role( 'artista_b' );
	$caps = $ddb ? $ddb->capabilities : array( 'read' => true );
	add_role( 'artista_ddb12', 'artista_ddb12', $caps );
}
add_action( 'init', 'trb_portal_register_ddb12_role', 18 );

/** Move users out of the two retired role containers, then remove them. */
function trb_portal_migrate_retired_artist_roles() {
	$migrations = array(
		'artista_e'         => 'artista_ddb12',
		'artisti_trb_basic' => 'artista_d',
	);

	foreach ( $migrations as $old_role => $new_role ) {
		if ( ! get_role( $old_role ) || ! get_role( $new_role ) ) {
			continue;
		}
		$user_ids = get_users( array( 'role' => $old_role, 'fields' => 'ids', 'number' => -1 ) );
		foreach ( $user_ids as $user_id ) {
			$user = new WP_User( $user_id );
			$user->add_role( $new_role );
			$user->remove_role( $old_role );
		}
		remove_role( $old_role );
	}
}
add_action( 'init', 'trb_portal_migrate_retired_artist_roles', 19 );

/** Keep the contractual groups in their intended order in role selectors. */
function trb_portal_order_artist_roles() {
	global $wpdb;

	$option_key = $wpdb->prefix . 'user_roles';
	$roles      = get_option( $option_key, array() );
	$order      = array( 'artista_a', 'artista_ddb12', 'artista_b', 'artista_c', 'artista_d' );
	if ( ! is_array( $roles ) || empty( $roles ) ) {
		return;
	}
	if ( isset( $roles['artista_ddb12'] ) ) {
		$roles['artista_ddb12']['name'] = 'artista_ddb12';
	}

	$rebuilt  = array();
	$inserted = false;
	foreach ( $roles as $slug => $settings ) {
		if ( in_array( $slug, $order, true ) ) {
			if ( ! $inserted ) {
				foreach ( $order as $ordered_slug ) {
					if ( isset( $roles[ $ordered_slug ] ) ) {
						$rebuilt[ $ordered_slug ] = $roles[ $ordered_slug ];
					}
				}
				$inserted = true;
			}
			continue;
		}
		$rebuilt[ $slug ] = $settings;
	}
	if ( ! $inserted ) {
		foreach ( $order as $ordered_slug ) {
			if ( isset( $roles[ $ordered_slug ] ) ) {
				$rebuilt[ $ordered_slug ] = $roles[ $ordered_slug ];
			}
		}
	}

	if ( $rebuilt !== $roles ) {
		update_option( $option_key, $rebuilt );
		wp_roles()->for_site();
	}
}
add_action( 'init', 'trb_portal_order_artist_roles', 21 );

/**
 * Idempotently add a distinct capability to each current contractual role.
 * No artist is moved here: the TRB Basic migration has its own explicit action.
 */
function trb_portal_register_capabilities() {
	foreach ( trb_portal_profiles() as $profile ) {
		$roles = array_merge( array( $profile['role'] ), isset( $profile['aliases'] ) ? (array) $profile['aliases'] : array() );
		foreach ( $roles as $role_slug ) {
			$role = get_role( $role_slug );
			if ( $role ) {
				$role->add_cap( 'trb_portal_access' );
				$role->add_cap( $profile['capability'] );
			}
		}
	}
}
add_action( 'init', 'trb_portal_register_capabilities', 20 );

