/** Resolve an Italian postcode locally, without transmitting profile data. */
function trb_portal_lookup_postcode( $postcode ) {
	$postcode = preg_replace( '/\D+/', '', (string) $postcode );
	if ( 5 !== strlen( $postcode ) ) return new WP_Error( 'invalid_postcode', 'Inserisci un CAP italiano di 5 cifre.' );
	static $archive = null;
	if ( null === $archive ) {
		$file = get_template_directory() . '/assets/data/italian-postcodes.json';
		$data = file_exists( $file ) ? json_decode( file_get_contents( $file ), true ) : array(); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
		$archive = isset( $data['postcodes'] ) && is_array( $data['postcodes'] ) ? $data['postcodes'] : array();
	}
	$places = isset( $archive[ $postcode ] ) ? $archive[ $postcode ] : array();
	if ( empty( $places ) ) return new WP_Error( 'postcode_not_found', 'CAP non trovato nell’archivio nazionale.' );
	return $places;
}

function trb_portal_territorial_archive() {
	static $archive = null;
	if ( null === $archive ) {
		$postcodes_file = get_template_directory() . '/assets/data/italian-postcodes.json';
		$municipalities_file = get_template_directory() . '/assets/data/italian-municipalities.json';
		$postcodes = file_exists( $postcodes_file ) ? json_decode( file_get_contents( $postcodes_file ), true ) : array(); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
		$municipalities = file_exists( $municipalities_file ) ? json_decode( file_get_contents( $municipalities_file ), true ) : array(); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
		$archive = is_array( $postcodes ) ? $postcodes : array();
		$archive['municipalities'] = array();
		foreach ( isset( $municipalities['municipalities'] ) ? $municipalities['municipalities'] : array() as $item ) {
			$parts = explode( '|', $item, 2 );
			if ( 2 === count( $parts ) ) $archive['municipalities'][] = array( 'city' => $parts[0], 'province' => $parts[1] );
		}
	}
	return $archive;
}

function trb_portal_find_municipalities( $search ) {
	$search = strtolower( remove_accents( trim( (string) $search ) ) );
	if ( strlen( $search ) < 2 ) return array();
	$archive = trb_portal_territorial_archive();
	$results = array();
	foreach ( isset( $archive['municipalities'] ) ? $archive['municipalities'] : array() as $municipality ) {
		$name = strtolower( remove_accents( $municipality['city'] ) );
		if ( 0 === strpos( $name, $search ) ) $results[] = $municipality;
		if ( count( $results ) >= 20 ) break;
	}
	return $results;
}

function trb_portal_find_municipality_exact( $city, $province = '' ) {
	$needle = strtolower( remove_accents( trim( (string) $city ) ) );
	$archive = trb_portal_territorial_archive();
	foreach ( isset( $archive['municipalities'] ) ? $archive['municipalities'] : array() as $municipality ) {
		if ( $needle === strtolower( remove_accents( $municipality['city'] ) ) && ( ! $province || strtoupper( $province ) === strtoupper( $municipality['province'] ) ) ) return $municipality;
	}
	return false;
}

function trb_portal_validate_mobile( $value ) {
	$value = preg_replace( '/[\s\.\-\(\)]+/', '', (string) $value );
	if ( 0 === strpos( $value, '0039' ) ) $value = '+39' . substr( $value, 4 );
	return preg_match( '/^(?:\+39)?3\d{9}$/', $value ) ? $value : false;
}

function trb_portal_validate_tax_code( $value ) {
	$value = strtoupper( preg_replace( '/\s+/', '', (string) $value ) );
	if ( ! preg_match( '/^[A-Z]{6}[0-9LMNPQRSTUV]{2}[ABCDEHLMPRST][0-9LMNPQRSTUV]{2}[A-Z][0-9LMNPQRSTUV]{3}[A-Z]$/', $value ) ) return false;
	$odd = array( '0'=>1,'1'=>0,'2'=>5,'3'=>7,'4'=>9,'5'=>13,'6'=>15,'7'=>17,'8'=>19,'9'=>21,'A'=>1,'B'=>0,'C'=>5,'D'=>7,'E'=>9,'F'=>13,'G'=>15,'H'=>17,'I'=>19,'J'=>21,'K'=>2,'L'=>4,'M'=>18,'N'=>20,'O'=>11,'P'=>3,'Q'=>6,'R'=>8,'S'=>12,'T'=>14,'U'=>16,'V'=>10,'W'=>22,'X'=>25,'Y'=>24,'Z'=>23 );
	$even = array();
	foreach ( range( '0', '9' ) as $char ) $even[ $char ] = (int) $char;
	foreach ( range( 'A', 'Z' ) as $index => $char ) $even[ $char ] = $index;
	$sum = 0;
	for ( $i = 0; $i < 15; $i++ ) $sum += 0 === $i % 2 ? $odd[ $value[ $i ] ] : $even[ $value[ $i ] ];
	return chr( 65 + ( $sum % 26 ) ) === $value[15] ? $value : false;
}

function trb_portal_rest_postcode( WP_REST_Request $request ) {
	$result = trb_portal_lookup_postcode( $request['postcode'] );
	return is_wp_error( $result ) ? new WP_REST_Response( array( 'message' => $result->get_error_message() ), 404 ) : rest_ensure_response( array( 'places' => $result, 'country' => 'Italia' ) );
}

function trb_portal_rest_municipalities( WP_REST_Request $request ) {
	return rest_ensure_response( array( 'places' => trb_portal_find_municipalities( $request->get_param( 'search' ) ) ) );
}

function trb_portal_register_rest_routes() {
	register_rest_route( 'trb/v1', '/postcode/(?P<postcode>\d{5})', array(
		'methods' => WP_REST_Server::READABLE,
		'callback' => 'trb_portal_rest_postcode',
		'permission_callback' => function() { return is_user_logged_in() && ( trb_portal_user_profile() || current_user_can( 'manage_options' ) ); },
	) );
	register_rest_route( 'trb/v1', '/municipalities', array(
		'methods' => WP_REST_Server::READABLE,
		'callback' => 'trb_portal_rest_municipalities',
		'permission_callback' => function() { return is_user_logged_in() && ( trb_portal_user_profile() || current_user_can( 'manage_options' ) ); },
		'args' => array( 'search' => array( 'required' => true, 'sanitize_callback' => 'sanitize_text_field' ) ),
	) );
}
add_action( 'rest_api_init', 'trb_portal_register_rest_routes' );

function trb_portal_artist_profile_is_complete( $user_id = 0 ) {
	$user_id = $user_id ? $user_id : get_current_user_id();
	$user = get_userdata( $user_id );
	if ( ! $user || '' === trim( (string) $user->first_name ) || '' === trim( (string) $user->last_name ) || '' === trim( (string) $user->user_email ) ) {
		return false;
	}
	$required = array( 'artist_name', 'phone', 'birth_date', 'birth_place', 'birth_province', 'tax_code', 'street', 'street_number', 'city', 'postal_code', 'province', 'country' );
	foreach ( $required as $field ) {
		if ( '' === trb_portal_artist_profile_value( $field, $user_id ) ) {
			return false;
		}
	}
	if ( ! trb_portal_has_valid_biography_content( $user_id ) ) {
		return false;
	}
	$platform_requirements = array(
		array( 'spotify_url', 'spotify_new' ),
		array( 'youtube_url', 'youtube_none' ),
		array( 'soundcloud_url', 'soundcloud_none' ),
	);
	foreach ( $platform_requirements as $requirement ) {
		if ( '' === trb_portal_artist_profile_value( $requirement[0], $user_id ) && '1' !== trb_portal_artist_profile_value( $requirement[1], $user_id ) ) {
			return false;
		}
	}
	if ( '' === trb_portal_artist_profile_value( 'live_fee', $user_id ) ) {
		return false;
	}

	$required_documents = array(
		'Carta d’identità — fronte',
		'Carta d’identità — retro',
		'Codice fiscale o tessera sanitaria — fronte',
		'Codice fiscale o tessera sanitaria — retro',
	);
	$received_documents = array();
	$has_photo          = false;
	foreach ( trb_portal_private_profile_files( $user_id ) as $file ) {
		if ( isset( $file['group'] ) && 'photo' === $file['group'] ) {
			$has_photo = true;
		}
		if ( ! empty( $file['label'] ) ) {
			$received_documents[] = $file['label'];
		}
	}

	return $has_photo && empty( array_diff( $required_documents, $received_documents ) );
}

/** Preserve the exact spelling and styling while preventing reuse by another account. */
function trb_portal_artist_name_owner( $artist_name, $exclude_user_id = 0 ) {
	$artist_name = trim( (string) $artist_name );
	if ( '' === $artist_name ) return 0;
	$users = get_users( array( 'fields' => 'ids', 'meta_key' => '_trb_artist_artist_name', 'meta_value' => $artist_name, 'meta_compare' => '=' ) );
	foreach ( $users as $user_id ) {
		if ( (int) $user_id !== (int) $exclude_user_id ) return (int) $user_id;
	}
	return 0;
}

/** Return a transparent completion score based on the same requirements that unlock a release. */
function trb_portal_artist_profile_completion( $user_id = 0 ) {
	$user_id = $user_id ? $user_id : get_current_user_id();
	$user = get_userdata( $user_id );
	$checks = array();
	$checks[] = $user && '' !== trim( (string) $user->first_name );
	$checks[] = $user && '' !== trim( (string) $user->last_name );
	$checks[] = $user && '' !== trim( (string) $user->user_email );
	foreach ( array( 'artist_name', 'phone', 'birth_date', 'birth_place', 'birth_province', 'tax_code', 'street', 'street_number', 'city', 'postal_code', 'province', 'country' ) as $field ) {
		$checks[] = '' !== trim( trb_portal_artist_profile_value( $field, $user_id ) );
	}
	$checks[] = trb_portal_has_valid_biography_content( $user_id );
	foreach ( array( array( 'spotify_url', 'spotify_new' ), array( 'youtube_url', 'youtube_none' ), array( 'soundcloud_url', 'soundcloud_none' ) ) as $requirement ) {
		$checks[] = '' !== trim( trb_portal_artist_profile_value( $requirement[0], $user_id ) ) || '1' === trb_portal_artist_profile_value( $requirement[1], $user_id );
	}
	$checks[] = '' !== trim( trb_portal_artist_profile_value( 'live_fee', $user_id ) );

	$document_labels = array();
	$has_photo = false;
	foreach ( trb_portal_private_profile_files( $user_id ) as $file ) {
		if ( isset( $file['group'] ) && 'photo' === $file['group'] ) $has_photo = true;
		if ( ! empty( $file['label'] ) ) $document_labels[] = $file['label'];
	}
	foreach ( array( 'Carta d’identità — fronte', 'Carta d’identità — retro', 'Codice fiscale o tessera sanitaria — fronte', 'Codice fiscale o tessera sanitaria — retro' ) as $label ) {
		$checks[] = in_array( $label, $document_labels, true );
	}
	$checks[] = $has_photo;

	$completed = count( array_filter( $checks ) );
	$total = count( $checks );
	return array(
		'completed' => $completed,
		'total' => $total,
		'remaining' => $total - $completed,
		'percentage' => $total ? (int) round( ( $completed / $total ) * 100 ) : 0,
	);
}

function trb_portal_handle_artist_profile() {
	if ( ! is_user_logged_in() ) {
		auth_redirect();
	}
	check_admin_referer( 'trb_portal_save_artist_profile', 'trb_portal_profile_nonce' );
	$user_id = get_current_user_id();
	$incoming_bytes = 0;
	foreach ( $_FILES as $incoming ) { // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized
		if ( isset( $incoming['size'] ) ) {
			$incoming_bytes += is_array( $incoming['size'] ) ? array_sum( array_map( 'absint', $incoming['size'] ) ) : absint( $incoming['size'] );
		}
	}
	if ( $incoming_bytes && function_exists( 'trb_resource_temp_storage_guard' ) && is_wp_error( trb_resource_temp_storage_guard( $incoming_bytes ) ) ) {
		wp_safe_redirect( add_query_arg( 'trb_profile', 'storage_waiting', get_permalink( get_option( 'trb_portal_dashboard_created' ) ) ) . '#profilo' );
		exit;
	}
	$profile = trb_portal_user_profile();
	$company_fields = array( 'company_name', 'company_vat', 'company_sdi', 'company_address' );
	$url_fields = array( 'spotify_url', 'apple_music_url', 'youtube_url', 'soundcloud_url', 'facebook_url', 'instagram_url', 'linkedin_url', 'tiktok_url', 'discord_url', 'twitch_url', 'x_url', 'snapchat_url', 'threads_url' );
	if ( isset( $_POST['trb_artist_artist_name'] ) ) {
		$submitted_artist_name = trim( sanitize_text_field( wp_unslash( $_POST['trb_artist_artist_name'] ) ) );
		if ( trb_portal_artist_name_owner( $submitted_artist_name, $user_id ) ) {
			wp_safe_redirect( add_query_arg( 'trb_profile', 'artist_name_taken', get_permalink( get_option( 'trb_portal_dashboard_created' ) ) ) . '#profilo' );
			exit;
		}
		$_POST['trb_artist_artist_name'] = $submitted_artist_name;
	}
	if ( isset( $_POST['trb_artist_company_section'] ) ) {
		$postcode = isset( $_POST['trb_artist_postal_code'] ) ? sanitize_text_field( wp_unslash( $_POST['trb_artist_postal_code'] ) ) : '';
		$city = isset( $_POST['trb_artist_city'] ) ? sanitize_text_field( wp_unslash( $_POST['trb_artist_city'] ) ) : '';
		$places = trb_portal_lookup_postcode( $postcode );
		$matched = false;
		if ( ! is_wp_error( $places ) ) foreach ( $places as $place ) {
			if ( strtolower( remove_accents( $city ) ) === strtolower( remove_accents( $place['city'] ) ) ) { $matched = $place; break; }
		}
		if ( ! $matched ) {
			wp_safe_redirect( add_query_arg( 'trb_profile', 'invalid_address', get_permalink( get_option( 'trb_portal_dashboard_created' ) ) ) . '#profilo' );
			exit;
		}
		$_POST['trb_artist_city'] = $matched['city'];
		$_POST['trb_artist_province'] = $matched['province'];
		$_POST['trb_artist_country'] = 'Italia';
	}
	if ( isset( $_POST['trb_artist_company_section'] ) ) {
		$birth_place = isset( $_POST['trb_artist_birth_place'] ) ? sanitize_text_field( wp_unslash( $_POST['trb_artist_birth_place'] ) ) : '';
		$birth_province = isset( $_POST['trb_artist_birth_province'] ) ? sanitize_text_field( wp_unslash( $_POST['trb_artist_birth_province'] ) ) : '';
		$birth_match = trb_portal_find_municipality_exact( $birth_place, $birth_province );
		$phone = isset( $_POST['trb_artist_phone'] ) ? trb_portal_validate_mobile( wp_unslash( $_POST['trb_artist_phone'] ) ) : false;
		$tax_code = isset( $_POST['trb_artist_tax_code'] ) ? trb_portal_validate_tax_code( wp_unslash( $_POST['trb_artist_tax_code'] ) ) : false;
		$error = ! $birth_match ? 'invalid_birthplace' : ( ! $phone ? 'invalid_phone' : ( ! $tax_code ? 'invalid_tax_code' : '' ) );
		if ( $error ) {
			wp_safe_redirect( add_query_arg( 'trb_profile', $error, get_permalink( get_option( 'trb_portal_dashboard_created' ) ) ) . '#profilo' );
			exit;
		}
		$_POST['trb_artist_birth_place'] = $birth_match['city'];
		$_POST['trb_artist_birth_province'] = $birth_match['province'];
		$_POST['trb_artist_phone'] = $phone;
		$_POST['trb_artist_tax_code'] = $tax_code;
	}
	foreach ( trb_portal_artist_profile_fields() as $key => $label ) {
		if ( ! isset( $_POST[ 'trb_artist_' . $key ] ) ) {
			continue;
		}
		if ( 'artist_name' === $key && '' !== trb_portal_artist_profile_value( 'artist_name', $user_id ) ) {
			continue;
		}
		if ( 'trb' === $profile && in_array( $key, $company_fields, true ) ) continue;
		$value = in_array( $key, $url_fields, true ) ? esc_url_raw( wp_unslash( $_POST[ 'trb_artist_' . $key ] ) ) : sanitize_text_field( wp_unslash( $_POST[ 'trb_artist_' . $key ] ) );
		update_user_meta( $user_id, '_trb_artist_' . $key, $value );
	}
	if ( 'trb' === $profile ) {
		delete_user_meta( $user_id, '_trb_artist_invoice_requested' );
		foreach ( $company_fields as $company_field ) delete_user_meta( $user_id, '_trb_artist_' . $company_field );
	} elseif ( isset( $_POST['trb_artist_invoice_requested'] ) || isset( $_POST['trb_artist_company_section'] ) ) {
		update_user_meta( $user_id, '_trb_artist_invoice_requested', isset( $_POST['trb_artist_invoice_requested'] ) ? '1' : '' );
	}
	if ( isset( $_POST['trb_artist_identity_section'] ) ) {
		$bio_upload = isset( $_FILES['trb_artist_bio_file'] ) ? $_FILES['trb_artist_bio_file'] : array(); // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized
		$has_bio    = ! empty( trb_portal_valid_biography_file( $user_id ) );
		if ( ! $has_bio && ( empty( $bio_upload['name'] ) || UPLOAD_ERR_OK !== (int) $bio_upload['error'] ) ) {
			wp_safe_redirect( add_query_arg( 'trb_profile', 'bio_required', get_permalink( get_option( 'trb_portal_dashboard_created' ) ) ) . '#profilo' );
			exit;
		}
		if ( ! empty( $bio_upload['name'] ) ) {
			$extension = strtolower( pathinfo( sanitize_file_name( $bio_upload['name'] ), PATHINFO_EXTENSION ) );
			if ( ! in_array( $extension, array( 'txt', 'docx', 'odt', 'rtf' ), true ) || (int) $bio_upload['size'] > 5 * MB_IN_BYTES ) {
				wp_safe_redirect( add_query_arg( 'trb_profile', 'bio_invalid', get_permalink( get_option( 'trb_portal_dashboard_created' ) ) ) . '#profilo' );
				exit;
			}
		}
		foreach ( array( 'spotify_new', 'apple_music_new', 'youtube_none', 'soundcloud_none' ) as $choice ) {
			update_user_meta( $user_id, '_trb_artist_' . $choice, isset( $_POST[ 'trb_artist_' . $choice ] ) ? '1' : '' );
		}
	}
	trb_portal_remove_private_profile_files( $user_id );
	trb_portal_handle_private_profile_uploads( $user_id );
	$bio_file = trb_portal_valid_biography_file( $user_id );
	if ( isset( $_POST['trb_artist_identity_section'] ) && empty( $bio_file ) ) {
		wp_safe_redirect( add_query_arg( 'trb_profile', 'bio_invalid', get_permalink( get_option( 'trb_portal_dashboard_created' ) ) ) . '#profilo' );
		exit;
	}
	if ( ! empty( $bio_file['name'] ) ) update_user_meta( $user_id, '_trb_artist_bio', 'Biografia allegata: ' . sanitize_text_field( $bio_file['name'] ) );
	do_action( 'trb_portal_artist_profile_saved', $user_id );
	wp_safe_redirect( add_query_arg( 'trb_profile', 'saved', get_permalink( get_option( 'trb_portal_dashboard_created' ) ) ) . '#profilo' );
	exit;
}
add_action( 'admin_post_trb_portal_save_artist_profile', 'trb_portal_handle_artist_profile' );

/**
 * Store identity files outside the normal Media Library and deny direct web
 * access. The stored metadata contains no public URL, only a private path.
 */
function trb_portal_private_upload_dir( $dirs ) {
	$dirs['subdir'] = '/trb-artist-private';
	$dirs['path']   = $dirs['basedir'] . $dirs['subdir'];
	$dirs['url']    = $dirs['baseurl'] . $dirs['subdir'];

	return $dirs;
}

function trb_portal_private_profile_files( $user_id = 0 ) {
	$files = get_user_meta( $user_id ? $user_id : get_current_user_id(), '_trb_artist_private_files', true );
	$files = is_array( $files ) ? $files : array();
	$changed = false;
	foreach ( $files as $index => $file ) {
		if ( empty( $file['id'] ) ) {
			$files[ $index ]['id'] = sha1( ( isset( $file['path'] ) ? $file['path'] : '' ) . '|' . $index );
			$changed = true;
		}
	}
	if ( $changed ) {
		update_user_meta( $user_id ? $user_id : get_current_user_id(), '_trb_artist_private_files', $files );
	}
	return $files;
}

function trb_portal_private_profile_file_by_group( $group, $user_id = 0 ) {
	foreach ( trb_portal_private_profile_files( $user_id ) as $file ) {
		if ( isset( $file['group'] ) && $group === $file['group'] ) return $file;
	}
	return array();
}

/** Return only a biography stored in one of the low-cost text formats. */
function trb_portal_valid_biography_file( $user_id = 0 ) {
	$file = trb_portal_private_profile_file_by_group( 'biography', $user_id );
	$extension = ! empty( $file['name'] ) ? strtolower( pathinfo( $file['name'], PATHINFO_EXTENSION ) ) : '';
	return in_array( $extension, array( 'txt', 'docx', 'odt', 'rtf' ), true ) ? $file : array();
}

function trb_portal_has_valid_biography_content( $user_id = 0 ) {
	return ! empty( trb_portal_valid_biography_file( $user_id ) ) ||
		( empty( trb_portal_private_profile_file_by_group( 'biography', $user_id ) ) && '' !== trim( (string) get_user_meta( $user_id ? $user_id : get_current_user_id(), '_trb_artist_bio', true ) ) );
}

function trb_portal_remove_private_profile_files( $user_id ) {
	$remove_ids = isset( $_POST['trb_artist_remove_files'] ) ? array_map( 'sanitize_text_field', (array) wp_unslash( $_POST['trb_artist_remove_files'] ) ) : array();
	if ( empty( $remove_ids ) ) {
		return;
	}
	$upload_dir = wp_upload_dir();
	$private_dir = realpath( trailingslashit( $upload_dir['basedir'] ) . 'trb-artist-private' );
	$remaining = array();
	foreach ( trb_portal_private_profile_files( $user_id ) as $file ) {
		if ( ! in_array( $file['id'], $remove_ids, true ) ) {
			$remaining[] = $file;
			continue;
		}
		$target = ! empty( $file['path'] ) ? realpath( trailingslashit( $upload_dir['basedir'] ) . ltrim( $file['path'], '/' ) ) : false;
		if ( $private_dir && $target && 0 === strpos( $target, $private_dir . DIRECTORY_SEPARATOR ) && is_file( $target ) ) {
			wp_delete_file( $target );
		}
	}
	update_user_meta( $user_id, '_trb_artist_private_files', $remaining );
}

function trb_portal_private_upload_items( $input_name ) {
	if ( empty( $_FILES[ $input_name ]['name'] ) ) {
		return array();
	}
	if ( ! is_array( $_FILES[ $input_name ]['name'] ) ) {
		return array( array( 'name' => $_FILES[ $input_name ]['name'], 'type' => $_FILES[ $input_name ]['type'], 'tmp_name' => $_FILES[ $input_name ]['tmp_name'], 'error' => $_FILES[ $input_name ]['error'], 'size' => $_FILES[ $input_name ]['size'] ) ); // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized
	}
	$items = array();
	foreach ( $_FILES[ $input_name ]['name'] as $index => $name ) {
		$items[] = array( 'name' => $name, 'type' => $_FILES[ $input_name ]['type'][ $index ], 'tmp_name' => $_FILES[ $input_name ]['tmp_name'][ $index ], 'error' => $_FILES[ $input_name ]['error'][ $index ], 'size' => $_FILES[ $input_name ]['size'][ $index ] ); // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized
	}
	return $items;
}

/** Remove byte-identical private files while preserving the first valid copy. */
function trb_portal_deduplicate_private_profile_files( $user_id ) {
	$upload_dir = wp_upload_dir();
	$private_dir = realpath( trailingslashit( $upload_dir['basedir'] ) . 'trb-artist-private' );
	$unique = array();
	$seen = array();
	$removed = 0;
	foreach ( trb_portal_private_profile_files( $user_id ) as $file ) {
		$target = ! empty( $file['path'] ) ? realpath( trailingslashit( $upload_dir['basedir'] ) . ltrim( $file['path'], '/' ) ) : false;
		if ( ! $private_dir || ! $target || 0 !== strpos( $target, $private_dir . DIRECTORY_SEPARATOR ) || ! is_file( $target ) ) {
			$unique[] = $file;
			continue;
		}
		$hash = hash_file( 'sha256', $target );
		$key = ( isset( $file['group'] ) ? $file['group'] : '' ) . '|' . ( isset( $file['label'] ) ? $file['label'] : '' ) . '|' . $hash;
		if ( isset( $seen[ $key ] ) ) {
			wp_delete_file( $target );
			$removed++;
			continue;
		}
		$seen[ $key ] = true;
		$file['sha256'] = $hash;
		$unique[] = $file;
	}
	update_user_meta( $user_id, '_trb_artist_private_files', $unique );
	return $removed;
}

function trb_portal_handle_private_profile_uploads( $user_id ) {
	if ( empty( $_FILES ) ) return;

	require_once ABSPATH . 'wp-admin/includes/file.php';
	trb_portal_deduplicate_private_profile_files( $user_id );
	$existing       = trb_portal_private_profile_files( $user_id );
	$known_hashes   = array();
	foreach ( $existing as $stored_file ) {
		if ( ! empty( $stored_file['sha256'] ) ) {
			$known_hashes[ ( isset( $stored_file['group'] ) ? $stored_file['group'] : '' ) . '|' . ( isset( $stored_file['label'] ) ? $stored_file['label'] : '' ) . '|' . $stored_file['sha256'] ] = true;
		}
	}
	$photos_count   = count( array_filter( $existing, function( $file ) { return isset( $file['group'] ) && 'photo' === $file['group']; } ) );
	$uploads        = array(
		'trb_artist_bio_file'     => array( 'group' => 'biography', 'label' => 'Biografia artistica', 'mimes' => array( 'txt' => 'text/plain', 'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'odt' => 'application/vnd.oasis.opendocument.text', 'rtf' => 'application/rtf' ) ),
		'trb_artist_photos'       => array( 'group' => 'photo', 'label' => 'Foto artista', 'mimes' => array( 'jpg|jpeg|jpe' => 'image/jpeg', 'png' => 'image/png', 'webp' => 'image/webp' ) ),
		'trb_artist_id_front'     => array( 'group' => 'identity', 'label' => 'Carta d’identità — fronte', 'mimes' => array( 'pdf' => 'application/pdf', 'jpg|jpeg|jpe' => 'image/jpeg', 'png' => 'image/png' ) ),
		'trb_artist_id_back'      => array( 'group' => 'identity', 'label' => 'Carta d’identità — retro', 'mimes' => array( 'pdf' => 'application/pdf', 'jpg|jpeg|jpe' => 'image/jpeg', 'png' => 'image/png' ) ),
		'trb_artist_tax_front'    => array( 'group' => 'tax_card', 'label' => 'Codice fiscale o tessera sanitaria — fronte', 'mimes' => array( 'pdf' => 'application/pdf', 'jpg|jpeg|jpe' => 'image/jpeg', 'png' => 'image/png' ) ),
		'trb_artist_tax_back'     => array( 'group' => 'tax_card', 'label' => 'Codice fiscale o tessera sanitaria — retro', 'mimes' => array( 'pdf' => 'application/pdf', 'jpg|jpeg|jpe' => 'image/jpeg', 'png' => 'image/png' ) ),
	);

	foreach ( $uploads as $input_name => $settings ) {
		foreach ( trb_portal_private_upload_items( $input_name ) as $upload ) {
			if ( empty( $upload['name'] ) || empty( $upload['tmp_name'] ) ) {
				continue;
			}
			if ( 'photo' === $settings['group'] && $photos_count >= 6 ) {
				break;
			}

			$file = array(
				'name'     => sanitize_file_name( $upload['name'] ),
				'type'     => isset( $upload['type'] ) ? sanitize_mime_type( $upload['type'] ) : '',
				'tmp_name' => $upload['tmp_name'], // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized
				'error'    => isset( $upload['error'] ) ? absint( $upload['error'] ) : UPLOAD_ERR_NO_FILE,
				'size'     => isset( $upload['size'] ) ? absint( $upload['size'] ) : 0,
			);
			if ( UPLOAD_ERR_OK !== $file['error'] ) {
				continue;
			}
			$incoming_hash = hash_file( 'sha256', $file['tmp_name'] );
			$hash_key = $settings['group'] . '|' . $settings['label'] . '|' . $incoming_hash;
			if ( isset( $known_hashes[ $hash_key ] ) ) {
				continue;
			}
			add_filter( 'upload_dir', 'trb_portal_private_upload_dir', 99 );
			$handled = wp_handle_upload( $file, array( 'test_form' => false, 'mimes' => $settings['mimes'] ) );
			remove_filter( 'upload_dir', 'trb_portal_private_upload_dir', 99 );
			if ( ! empty( $handled['error'] ) || empty( $handled['file'] ) ) {
				continue;
			}
			if ( 'biography' === $settings['group'] ) {
				$upload_dir = wp_upload_dir();
				$private_dir = realpath( trailingslashit( $upload_dir['basedir'] ) . 'trb-artist-private' );
				$kept = array();
				foreach ( $existing as $stored_file ) {
					if ( isset( $stored_file['group'] ) && 'biography' === $stored_file['group'] ) {
						$target = ! empty( $stored_file['path'] ) ? realpath( trailingslashit( $upload_dir['basedir'] ) . ltrim( $stored_file['path'], '/' ) ) : false;
						if ( $private_dir && $target && 0 === strpos( $target, $private_dir . DIRECTORY_SEPARATOR ) && is_file( $target ) ) wp_delete_file( $target );
						continue;
					}
					$kept[] = $stored_file;
				}
				$existing = $kept;
			}

			$upload_dir = wp_upload_dir();
			$private_dir = trailingslashit( $upload_dir['basedir'] ) . 'trb-artist-private';
			if ( wp_mkdir_p( $private_dir ) ) {
				$rules_file = trailingslashit( $private_dir ) . '.htaccess';
				if ( ! file_exists( $rules_file ) ) {
					file_put_contents( $rules_file, "Require all denied\nDeny from all\nOptions -Indexes\n" ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_file_put_contents
				}
			}

			$existing[] = array(
				'id'    => wp_generate_uuid4(),
				'group' => $settings['group'],
				'label' => $settings['label'],
				'name'  => basename( $handled['file'] ),
				'path'  => str_replace( trailingslashit( $upload_dir['basedir'] ), '', $handled['file'] ),
				'type'  => $handled['type'],
				'time'  => time(),
				'sha256' => $incoming_hash,
			);
			$known_hashes[ $hash_key ] = true;
			if ( 'photo' === $settings['group'] ) {
				$photos_count++;
			}
		}
	}

	update_user_meta( $user_id, '_trb_artist_private_files', $existing );
	trb_portal_deduplicate_private_profile_files( $user_id );
}

function trb_portal_user_releases() {
	return get_posts(
		array(
			'post_type'      => 'trb_release',
			'post_status'    => array( 'publish', 'private', 'pending', 'draft' ),
			'author'         => get_current_user_id(),
			'posts_per_page' => 30,
			'orderby'        => 'date',
			'order'          => 'DESC',
		)
	);
}

/** Number of DDB12 practices created in the current calendar month. */
function trb_portal_ddb12_monthly_release_count( $user_id = 0 ) {
	$user_id = $user_id ? absint( $user_id ) : get_current_user_id();
	if ( ! $user_id ) {
		return 0;
	}

	$query = new WP_Query(
		array(
			'post_type'      => 'trb_release',
			'post_status'    => 'publish',
			'author'         => $user_id,
			'fields'         => 'ids',
			'posts_per_page' => 1,
			'date_query'     => array(
				array(
					'year'     => (int) wp_date( 'Y' ),
					'monthnum' => (int) wp_date( 'n' ),
				),
			),
		)
	);

	return (int) $query->found_posts;
}

function trb_portal_ddb12_limit_reached( $user_id = 0 ) {
	$user_id = $user_id ? absint( $user_id ) : get_current_user_id();
	$user    = $user_id ? get_userdata( $user_id ) : false;

	return $user && 'ddb12' === trb_portal_user_profile( $user ) && trb_portal_ddb12_monthly_release_count( $user_id ) >= 1;
}

function trb_portal_ddb12_next_reset_label() {
	$timezone = wp_timezone();
	$next     = new DateTimeImmutable( 'first day of next month 00:00:00', $timezone );

	return wp_date( 'j F Y', $next->getTimestamp(), $timezone );
}

function trb_portal_ddb12_limit_redirect() {
	wp_safe_redirect( add_query_arg( 'trb_release', 'monthly_limit', get_permalink( get_option( 'trb_portal_dashboard_created' ) ) ) . '#release' );
	exit;
}

/**
 * Rebuild the release metadata from one compact JSON field. Large catalogues
 * can contain more values than PHP's max_input_vars limit, so the browser does
 * not send thousands of independent multipart fields on the final request.
 */
function trb_portal_set_nested_post_value( $name, $value ) {
	if ( ! preg_match( '/^([A-Za-z0-9_]+)((?:\[[A-Za-z0-9_-]*\])*)$/', $name, $matches ) || 0 !== strpos( $matches[1], 'trb_' ) ) return;
	$keys = array( $matches[1] );
	if ( '' !== $matches[2] ) {
		preg_match_all( '/\[([A-Za-z0-9_-]*)\]/', $matches[2], $parts );
		$keys = array_merge( $keys, $parts[1] );
	}
	$target =& $_POST;
	$last = array_pop( $keys );
	foreach ( $keys as $key ) {
		if ( '' === $key ) {
			$target[] = array();
			end( $target );
			$key = key( $target );
		}
		if ( ! isset( $target[ $key ] ) || ! is_array( $target[ $key ] ) ) $target[ $key ] = array();
		$target =& $target[ $key ];
	}
	$value = wp_slash( (string) $value );
	if ( '' === $last ) $target[] = $value;
	else $target[ $last ] = $value;
}

function trb_portal_hydrate_release_post() {
	$action = isset( $_POST['action'] ) ? sanitize_key( wp_unslash( $_POST['action'] ) ) : '';
	if ( ! in_array( $action, array( 'trb_portal_start_release', 'trb_portal_replace_release_file' ), true ) || empty( $_POST['trb_release_payload_json'] ) ) return;
	$json = wp_unslash( $_POST['trb_release_payload_json'] );
	if ( ! is_string( $json ) || strlen( $json ) > 2 * MB_IN_BYTES ) return;
	$pairs = json_decode( $json, true );
	if ( ! is_array( $pairs ) || count( $pairs ) > 20000 ) return;
	foreach ( $pairs as $pair ) {
		if ( ! is_array( $pair ) || 2 !== count( $pair ) || ! is_string( $pair[0] ) || ! is_scalar( $pair[1] ) ) continue;
		trb_portal_set_nested_post_value( $pair[0], $pair[1] );
	}
}
add_action( 'admin_init', 'trb_portal_hydrate_release_post', 0 );

function trb_portal_release_staging_root( $user_id = 0 ) {
	$uploads = wp_upload_dir();
	$user_id = $user_id ? absint( $user_id ) : get_current_user_id();
	return trailingslashit( $uploads['basedir'] ) . 'trb-release-staging/' . $user_id;
}

function trb_portal_release_staging_session_dir( $session, $create = false ) {
	$session = sanitize_text_field( $session );
	if ( ! preg_match( '/^[a-f0-9-]{36}$/i', $session ) ) return false;
	$root = trb_portal_release_staging_root();
	$directory = trailingslashit( $root ) . $session;
	if ( $create ) {
		if ( ! wp_mkdir_p( $directory ) ) return false;
		$uploads = wp_upload_dir();
		$protected_root = trailingslashit( $uploads['basedir'] ) . 'trb-release-staging';
		$rules = trailingslashit( $protected_root ) . '.htaccess';
		if ( ! file_exists( $rules ) ) file_put_contents( $rules, "Require all denied\nDeny from all\nOptions -Indexes\n" ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_file_put_contents
	}
	return $directory;
}

function trb_portal_release_is_staged_path( $path ) {
	$root = realpath( trb_portal_release_staging_root() );
	$path = realpath( $path );
	return $root && $path && is_file( $path ) && 0 === strpos( $path, $root . DIRECTORY_SEPARATOR );
}

function trb_portal_cleanup_release_staging_session( $session ) {
	$directory = trb_portal_release_staging_session_dir( $session, false );
	$root = realpath( trb_portal_release_staging_root() );
	$directory = $directory ? realpath( $directory ) : false;
	if ( ! $root || ! $directory || 0 !== strpos( $directory, $root . DIRECTORY_SEPARATOR ) ) return;
	foreach ( glob( trailingslashit( $directory ) . '*' ) ?: array() as $path ) if ( is_file( $path ) ) wp_delete_file( $path );
	@rmdir( $directory ); // phpcs:ignore WordPress.PHP.NoSilencedErrors.Discouraged,WordPress.WP.AlternativeFunctions.file_system_operations_rmdir
}

function trb_portal_cleanup_expired_release_staging() {
	$key = '_trb_release_staging_cleanup_' . get_current_user_id();
	if ( get_transient( $key ) ) return;
	set_transient( $key, 1, HOUR_IN_SECONDS );
	$root = trb_portal_release_staging_root();
	foreach ( glob( trailingslashit( $root ) . '*' ) ?: array() as $directory ) {
		if ( ! is_dir( $directory ) || filemtime( $directory ) > time() - DAY_IN_SECONDS ) continue;
		trb_portal_cleanup_release_staging_session( basename( $directory ) );
	}
}

function trb_portal_stage_release_chunk() {
	if ( ! is_user_logged_in() ) wp_send_json_error( array( 'message' => 'Sessione non valida: aggiorna la pagina e accedi nuovamente.' ), 401 );
	trb_portal_cleanup_expired_release_staging();
	if ( empty( $_POST['trb_release_stage_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['trb_release_stage_nonce'] ) ), 'trb_portal_stage_release' ) ) wp_send_json_error( array( 'message' => 'La pagina è scaduta: aggiornala prima di riprovare.' ), 403 );
	$session = isset( $_POST['session'] ) ? sanitize_text_field( wp_unslash( $_POST['session'] ) ) : '';
	$file_key = isset( $_POST['file_key'] ) ? sanitize_key( wp_unslash( $_POST['file_key'] ) ) : '';
	$file_name = isset( $_POST['file_name'] ) ? sanitize_file_name( wp_unslash( $_POST['file_name'] ) ) : '';
	$file_type = isset( $_POST['file_type'] ) ? sanitize_mime_type( wp_unslash( $_POST['file_type'] ) ) : '';
	$file_size = isset( $_POST['file_size'] ) ? absint( $_POST['file_size'] ) : 0;
	$last_modified = isset( $_POST['last_modified'] ) ? absint( $_POST['last_modified'] ) : 0;
	$chunk_index = isset( $_POST['chunk_index'] ) ? absint( $_POST['chunk_index'] ) : 0;
	$chunk_total = isset( $_POST['chunk_total'] ) ? absint( $_POST['chunk_total'] ) : 0;
	if ( ! preg_match( '/^[a-f0-9-]{36}$/i', $session ) || ! preg_match( '/^f[0-9]{1,4}$/', $file_key ) || '' === $file_name || $file_size < 1 || $file_size > 1024 * MB_IN_BYTES || $chunk_total < 1 || $chunk_total > 512 || $chunk_index >= $chunk_total ) wp_send_json_error( array( 'message' => 'Parametri del caricamento non validi.' ), 422 );
	$chunk = ! empty( $_FILES['trb_release_chunk'] ) ? $_FILES['trb_release_chunk'] : array(); // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized
	if ( empty( $chunk['tmp_name'] ) || UPLOAD_ERR_OK !== (int) ( $chunk['error'] ?? UPLOAD_ERR_NO_FILE ) || ! is_uploaded_file( $chunk['tmp_name'] ) || (int) $chunk['size'] < 1 || (int) $chunk['size'] > 6 * MB_IN_BYTES ) wp_send_json_error( array( 'message' => 'Un blocco del file non è arrivato correttamente al server.' ), 422 );
	$directory = trb_portal_release_staging_session_dir( $session, true );
	if ( ! $directory ) wp_send_json_error( array( 'message' => 'Il server non riesce a preparare l’area temporanea del file.' ), 500 );
	$part_path = trailingslashit( $directory ) . $file_key . '.part';
	$meta_path = trailingslashit( $directory ) . $file_key . '.json';
	$meta = file_exists( $meta_path ) ? json_decode( (string) file_get_contents( $meta_path ), true ) : array(); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
	$signature = array( 'name' => $file_name, 'type' => $file_type, 'size' => $file_size, 'last_modified' => $last_modified, 'total' => $chunk_total );
	$matches = is_array( $meta );
	foreach ( $signature as $key => $value ) if ( ! isset( $meta[ $key ] ) || (string) $meta[ $key ] !== (string) $value ) $matches = false;
	if ( ! $matches ) {
		if ( 0 !== $chunk_index ) wp_send_json_error( array( 'message' => 'La sequenza del caricamento è incompleta. Riprova senza ricaricare la pagina.' ), 409 );
		if ( function_exists( 'trb_resource_temp_storage_guard' ) ) {
			$guard = trb_resource_temp_storage_guard( $file_size );
			if ( is_wp_error( $guard ) ) wp_send_json_error( array( 'message' => trb_portal_release_upload_error_message( $guard->get_error_code() ) ), 507 );
		}
		if ( file_exists( $part_path ) ) wp_delete_file( $part_path );
		$meta = $signature + array( 'next_chunk' => 0, 'complete' => false );
	}
	$next_chunk = isset( $meta['next_chunk'] ) ? absint( $meta['next_chunk'] ) : 0;
	if ( $chunk_index < $next_chunk ) wp_send_json_success( array( 'next_chunk' => $next_chunk, 'complete' => ! empty( $meta['complete'] ) ) );
	if ( $chunk_index > $next_chunk ) wp_send_json_error( array( 'message' => 'È arrivato un blocco fuori sequenza. Riprova senza ricaricare la pagina.' ), 409 );
	$source = fopen( $chunk['tmp_name'], 'rb' ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fopen
	$target = fopen( $part_path, 0 === $chunk_index ? 'wb' : 'ab' ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fopen
	if ( ! $source || ! $target ) {
		if ( $source ) fclose( $source ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fclose
		if ( $target ) fclose( $target ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fclose
		wp_send_json_error( array( 'message' => 'Il server non riesce a scrivere il file temporaneo.' ), 500 );
	}
	flock( $target, LOCK_EX ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_flock
	$written = stream_copy_to_stream( $source, $target ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_stream_copy_to_stream
	flock( $target, LOCK_UN ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_flock
	fclose( $source ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fclose
	fclose( $target ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fclose
	if ( false === $written || (int) $written !== (int) $chunk['size'] ) {
		wp_delete_file( $part_path );
		wp_delete_file( $meta_path );
		wp_send_json_error( array( 'message' => 'Il server ha scritto soltanto una parte del blocco ricevuto. Il file temporaneo è stato annullato.' ), 500 );
	}
	$meta['next_chunk'] = $chunk_index + 1;
	$meta['complete'] = $meta['next_chunk'] === $chunk_total;
	if ( $meta['complete'] && (int) filesize( $part_path ) !== $file_size ) {
		wp_delete_file( $part_path );
		wp_delete_file( $meta_path );
		wp_send_json_error( array( 'message' => 'La dimensione finale del file non coincide con quella originale. Il caricamento è stato annullato.' ), 422 );
	}
	if ( false === file_put_contents( $meta_path, wp_json_encode( $meta ), LOCK_EX ) ) { // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_file_put_contents
		wp_delete_file( $part_path );
		wp_send_json_error( array( 'message' => 'Il server non riesce a registrare l’avanzamento del caricamento. Il file temporaneo è stato annullato.' ), 500 );
	}
	wp_send_json_success( array( 'next_chunk' => $meta['next_chunk'], 'complete' => $meta['complete'] ) );
}
add_action( 'admin_post_trb_portal_stage_release_chunk', 'trb_portal_stage_release_chunk' );

function trb_portal_staged_release_upload_item( $input_name, $index = null ) {
	if ( empty( $_POST['trb_staged_uploads_json'] ) ) return array();
	$map = json_decode( wp_unslash( $_POST['trb_staged_uploads_json'] ), true );
	$field_name = null === $index ? $input_name : $input_name . '[' . absint( $index ) . ']';
	$entry = is_array( $map ) && isset( $map[ $field_name ] ) && is_array( $map[ $field_name ] ) ? $map[ $field_name ] : array();
	$session = isset( $entry['session'] ) ? sanitize_text_field( $entry['session'] ) : '';
	$submission_token = isset( $_POST['trb_release_submission_token'] ) ? sanitize_text_field( wp_unslash( $_POST['trb_release_submission_token'] ) ) : '';
	$file_key = isset( $entry['key'] ) ? sanitize_key( $entry['key'] ) : '';
	if ( ! $entry || ! hash_equals( $submission_token, $session ) || ! preg_match( '/^f[0-9]{1,4}$/', $file_key ) ) return array();
	$directory = trb_portal_release_staging_session_dir( $session, false );
	$part_path = $directory ? trailingslashit( $directory ) . $file_key . '.part' : '';
	$meta_path = $directory ? trailingslashit( $directory ) . $file_key . '.json' : '';
	$meta = $meta_path && file_exists( $meta_path ) ? json_decode( (string) file_get_contents( $meta_path ), true ) : array(); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
	if ( ! is_array( $meta ) || empty( $meta['complete'] ) || ! trb_portal_release_is_staged_path( $part_path ) || (int) filesize( $part_path ) !== (int) ( $meta['size'] ?? 0 ) ) return array();
	return array( 'name' => sanitize_file_name( $meta['name'] ?? '' ), 'type' => sanitize_mime_type( $meta['type'] ?? '' ), 'tmp_name' => $part_path, 'error' => UPLOAD_ERR_OK, 'size' => (int) filesize( $part_path ), '_trb_staged' => true, '_trb_staging_session' => $session );
}

function trb_portal_release_upload_item( $input_name, $index = null ) {
	if ( empty( $_FILES[ $input_name ] ) ) return trb_portal_staged_release_upload_item( $input_name, $index );
	$file = $_FILES[ $input_name ]; // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized
	if ( null !== $index ) {
		if ( ! isset( $file['name'][ $index ] ) ) return array();
		return array( 'name' => $file['name'][ $index ], 'type' => $file['type'][ $index ], 'tmp_name' => $file['tmp_name'][ $index ], 'error' => $file['error'][ $index ], 'size' => $file['size'][ $index ] ); // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized
	}
	return array( 'name' => $file['name'], 'type' => $file['type'], 'tmp_name' => $file['tmp_name'], 'error' => $file['error'], 'size' => $file['size'] ); // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized
}

/**
 * Read the technical format directly from a RIFF/WAVE file. Browser MIME
 * values and file extensions are not trusted for release masters.
 */
function trb_portal_wav_spec( $path ) {
	$handle = @fopen( $path, 'rb' ); // phpcs:ignore WordPress.PHP.NoSilencedErrors.Discouraged,WordPress.WP.AlternativeFunctions.file_system_operations_fopen
	if ( ! $handle ) return new WP_Error( 'invalid_audio' );
	$header = fread( $handle, 12 ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fread
	if ( 12 !== strlen( $header ) || 'RIFF' !== substr( $header, 0, 4 ) || 'WAVE' !== substr( $header, 8, 4 ) ) {
		fclose( $handle ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fclose
		return new WP_Error( 'invalid_audio' );
	}
	$spec = null;
	$data_size = null;
	while ( ! feof( $handle ) ) {
		$chunk = fread( $handle, 8 ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fread
		if ( 8 !== strlen( $chunk ) ) break;
		$size_data = unpack( 'Vsize', substr( $chunk, 4, 4 ) );
		$size = isset( $size_data['size'] ) ? (int) $size_data['size'] : 0;
		if ( 'fmt ' === substr( $chunk, 0, 4 ) && $size >= 16 ) {
			$read_size = min( $size, 64 );
			$format_data = fread( $handle, $read_size ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fread
			if ( strlen( $format_data ) >= 16 ) {
				$values = unpack( 'vformat/vchannels/Vsample_rate/Vbyte_rate/vblock_align/vbits_per_sample', substr( $format_data, 0, 16 ) );
				$spec = array(
					'format'      => isset( $values['format'] ) ? (int) $values['format'] : 0,
					'channels'    => isset( $values['channels'] ) ? (int) $values['channels'] : 0,
					'sample_rate' => isset( $values['sample_rate'] ) ? (int) $values['sample_rate'] : 0,
					'byte_rate'   => isset( $values['byte_rate'] ) ? (int) $values['byte_rate'] : 0,
					'bit_depth'   => isset( $values['bits_per_sample'] ) ? (int) $values['bits_per_sample'] : 0,
				);
			}
			if ( $size > $read_size ) fseek( $handle, $size - $read_size, SEEK_CUR );
			if ( $size % 2 ) fseek( $handle, 1, SEEK_CUR );
			if ( null !== $data_size ) break;
			continue;
		}
		if ( 'data' === substr( $chunk, 0, 4 ) ) {
			$data_size = $size;
			if ( is_array( $spec ) ) break;
		}
		fseek( $handle, $size + ( $size % 2 ), SEEK_CUR );
	}
	fclose( $handle ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fclose
	if ( ! is_array( $spec ) || ! in_array( $spec['format'], array( 1, 65534 ), true ) || null === $data_size || $spec['byte_rate'] <= 0 ) return new WP_Error( 'invalid_audio' );
	$spec['data_size'] = $data_size;
	$spec['duration_seconds'] = $data_size / $spec['byte_rate'];
	return $spec;
}

/** Validate the real structure of the small text documents accepted by the portal. */
function trb_portal_validate_release_document( $path, $extension ) {
	$head = file_get_contents( $path, false, null, 0, 4096 ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
	if ( false === $head || '' === $head ) return false;
	if ( 'txt' === $extension ) return false === strpos( $head, "\0" );
	if ( 'rtf' === $extension ) return 0 === strpos( ltrim( $head ), '{\\rtf' );
	if ( ! in_array( $extension, array( 'docx', 'odt' ), true ) || 0 !== strpos( $head, "PK\x03\x04" ) ) return false;
	if ( ! class_exists( 'ZipArchive' ) ) return true;
	$zip = new ZipArchive();
	if ( true !== $zip->open( $path ) ) return false;
	$names = array();
	for ( $index = 0; $index < $zip->numFiles; $index++ ) {
		$name = (string) $zip->getNameIndex( $index );
		$names[] = $name;
		if ( preg_match( '/(?:vbaProject\.bin|\.(?:exe|com|js|vbs|bat|cmd|ps1))$/i', $name ) ) { $zip->close(); return false; }
	}
	$valid = 'docx' === $extension
		? in_array( '[Content_Types].xml', $names, true ) && in_array( 'word/document.xml', $names, true )
		: false !== $zip->locateName( 'mimetype' ) && 'application/vnd.oasis.opendocument.text' === trim( (string) $zip->getFromName( 'mimetype' ) );
	$zip->close();
	return $valid;
}

function trb_portal_validate_release_upload( $file, $kind ) {
	$is_staged = ! empty( $file['_trb_staged'] ) && ! empty( $file['tmp_name'] ) && trb_portal_release_is_staged_path( $file['tmp_name'] );
	if ( empty( $file['name'] ) || UPLOAD_ERR_OK !== (int) ( $file['error'] ?? UPLOAD_ERR_NO_FILE ) || empty( $file['tmp_name'] ) || ( ! $is_staged && ! is_uploaded_file( $file['tmp_name'] ) ) ) return new WP_Error( 'missing_' . $kind );
	if ( ! $is_staged && function_exists( 'trb_resource_temp_storage_guard' ) ) {
		$storage_guard = trb_resource_temp_storage_guard( (int) $file['size'] );
		if ( is_wp_error( $storage_guard ) ) return $storage_guard;
	}
	$name = sanitize_file_name( $file['name'] );
	$extension = strtolower( pathinfo( $name, PATHINFO_EXTENSION ) );
	if ( 'cover' === $kind ) {
		if ( ! in_array( $extension, array( 'jpg', 'jpeg', 'png' ), true ) || (int) $file['size'] > 20 * MB_IN_BYTES ) return new WP_Error( 'invalid_cover' );
		$image = @getimagesize( $file['tmp_name'] ); // phpcs:ignore WordPress.PHP.NoSilencedErrors.Discouraged
		if ( ! $image || $image[0] < 1500 || $image[1] < 1500 || $image[0] !== $image[1] || ! in_array( (int) $image[2], array( IMAGETYPE_JPEG, IMAGETYPE_PNG ), true ) ) return new WP_Error( 'invalid_cover' );
	} elseif ( 'audio' === $kind ) {
		if ( 'wav' !== $extension || (int) $file['size'] > 1024 * MB_IN_BYTES ) return new WP_Error( 'invalid_audio' );
		$spec = trb_portal_wav_spec( $file['tmp_name'] );
		if ( is_wp_error( $spec ) || 2 !== (int) $spec['channels'] || $spec['sample_rate'] < 44100 || $spec['sample_rate'] > 96000 || $spec['bit_depth'] < 16 || $spec['bit_depth'] > 24 ) return new WP_Error( 'invalid_audio' );
	} elseif ( 'rights_document' === $kind ) {
		if ( 'pdf' !== $extension || (int) $file['size'] > 10 * MB_IN_BYTES ) return new WP_Error( 'invalid_rights_document' );
		$head = file_get_contents( $file['tmp_name'], false, null, 0, 8 ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
		if ( false === $head || 0 !== strpos( $head, '%PDF-' ) ) return new WP_Error( 'invalid_rights_document' );
	} else {
		if ( ! in_array( $extension, array( 'txt', 'docx', 'odt', 'rtf' ), true ) || (int) $file['size'] > 5 * MB_IN_BYTES || ! trb_portal_validate_release_document( $file['tmp_name'], $extension ) ) return new WP_Error( 'invalid_' . $kind );
	}
	return true;
}

function trb_portal_release_audio_name_segment( $value, $fallback ) {
	$value = trim( wp_strip_all_tags( (string) $value ) );
	$value = preg_replace( '/[\\\\\/:*?"<>|]+/u', '-', $value );
	$value = preg_replace( '/\s+/u', '_', $value );
	$value = preg_replace( '/_+/u', '_', $value );
	$value = trim( $value, " .-_\t\n\r\0\x0B" );
	return '' !== $value ? $value : $fallback;
}

function trb_portal_release_audio_filename( $release_id, $track_index, $track_title, $audio_status ) {
	$release = get_post( $release_id );
	$artist_name = $release ? trb_portal_artist_profile_value( 'artist_name', $release->post_author ) : '';
	$artist = trb_portal_release_audio_name_segment( $artist_name, 'Artista' );
	$title = trb_portal_release_audio_name_segment( $track_title, 'Brano_' . ( absint( $track_index ) + 1 ) );
	$suffix = 'mastering' === $audio_status ? 'PRE-MST' : 'MST';
	return sprintf( '%02d)_%s_-_%s_(%s).wav', absint( $track_index ) + 1, $artist, $title, $suffix );
}

function trb_portal_release_track_duration_seconds( $track ) {
	$duration = isset( $track['duration'] ) ? (string) $track['duration'] : '';
	if ( ! preg_match( '/^(\d{2}):([0-5]\d)$/', $duration, $parts ) ) return 0;
	return ( (int) $parts[1] * 60 ) + (int) $parts[2];
}

function trb_portal_store_release_upload( $release_id, $file, $kind, $track_index = null, $metadata = array() ) {
	$valid = trb_portal_validate_release_upload( $file, $kind );
	if ( is_wp_error( $valid ) ) return $valid;
	$uploads = wp_upload_dir();
	$relative_dir = 'trb-release-private/' . absint( $release_id );
	$directory = trailingslashit( $uploads['basedir'] ) . $relative_dir;
	if ( ! wp_mkdir_p( $directory ) ) return new WP_Error( 'release_storage_failed' );
	$rules = trailingslashit( $uploads['basedir'] ) . 'trb-release-private/.htaccess';
	if ( ! file_exists( $rules ) ) file_put_contents( $rules, "Require all denied\nDeny from all\nOptions -Indexes\n" ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_file_put_contents
	$prefix = 'cover' === $kind ? 'Copertina' : ( 'presentation' === $kind ? 'Presentazione release' : ( 'audio' === $kind ? 'Audio brano ' . ( absint( $track_index ) + 1 ) : ( 'rights_document' === $kind ? 'Licenza diritti brano ' . ( absint( $track_index ) + 1 ) : 'Testo brano ' . ( absint( $track_index ) + 1 ) ) ) );
	$extension = strtolower( pathinfo( sanitize_file_name( $file['name'] ), PATHINFO_EXTENSION ) );
	if ( 'audio' === $kind ) {
		$canonical_filename = trb_portal_release_audio_filename(
			$release_id,
			$track_index,
			isset( $metadata['track_title'] ) ? $metadata['track_title'] : '',
			isset( $metadata['audio_status'] ) ? $metadata['audio_status'] : 'mastered'
		);
		$filename = ! empty( $metadata['replacement'] )
			? wp_unique_filename( $directory, preg_replace( '/\.wav$/i', '.replacement.wav', $canonical_filename ) )
			: $canonical_filename;
	} else {
		$filename = wp_unique_filename( $directory, sanitize_file_name( $prefix . '.' . $extension ) );
	}
	$target = trailingslashit( $directory ) . $filename;
	if ( ! empty( $file['_trb_staged'] ) ) {
		$moved = @rename( $file['tmp_name'], $target ); // phpcs:ignore WordPress.PHP.NoSilencedErrors.Discouraged,WordPress.WP.AlternativeFunctions.rename_rename
		if ( ! $moved ) {
			$moved = copy( $file['tmp_name'], $target ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_copy
			if ( $moved ) wp_delete_file( $file['tmp_name'] );
		}
	} else {
		$moved = move_uploaded_file( $file['tmp_name'], $target );
	}
	if ( ! $moved ) return new WP_Error( 'release_storage_failed' );
	$stored = array( 'kind' => $kind, 'track' => null === $track_index ? null : absint( $track_index ), 'name' => 'audio' === $kind ? $canonical_filename : $filename, 'original_name' => sanitize_file_name( $file['name'] ), 'path' => $relative_dir . '/' . $filename, 'type' => sanitize_mime_type( $file['type'] ), 'size' => filesize( $target ), 'sha256' => hash_file( 'sha256', $target ) );
	if ( 'audio' === $kind ) {
		$spec = trb_portal_wav_spec( $target );
		if ( ! is_wp_error( $spec ) ) $stored['audio_spec'] = $spec;
	}
	return $stored;
}

function trb_portal_delete_release_files( $files ) {
	$uploads = wp_upload_dir();
	$base = realpath( trailingslashit( $uploads['basedir'] ) . 'trb-release-private' );
	foreach ( (array) $files as $file ) {
		$target = ! empty( $file['path'] ) ? realpath( trailingslashit( $uploads['basedir'] ) . ltrim( $file['path'], '/' ) ) : false;
		if ( $base && $target && 0 === strpos( $target, $base . DIRECTORY_SEPARATOR ) && is_file( $target ) ) wp_delete_file( $target );
	}
}

function trb_portal_release_file_url( $release_id, $file_index, $inline = false ) {
	$url = add_query_arg(
		array( 'action' => 'trb_portal_release_file', 'release_id' => absint( $release_id ), 'file_index' => absint( $file_index ), 'view' => $inline ? '1' : '0' ),
		admin_url( 'admin-post.php' )
	);
	return wp_nonce_url( $url, 'trb_portal_release_file_' . absint( $release_id ) . '_' . absint( $file_index ) );
}

function trb_portal_current_user_can_access_release( $release_id ) {
	$post = get_post( $release_id );
	return $post && 'trb_release' === $post->post_type && ( current_user_can( 'manage_options' ) || (int) $post->post_author === get_current_user_id() );
}

function trb_portal_serve_release_file() {
	if ( ! is_user_logged_in() ) auth_redirect();
	$release_id = isset( $_GET['release_id'] ) ? absint( $_GET['release_id'] ) : 0;
	$file_index = isset( $_GET['file_index'] ) ? absint( $_GET['file_index'] ) : 0;
	check_admin_referer( 'trb_portal_release_file_' . $release_id . '_' . $file_index );
	if ( ! trb_portal_current_user_can_access_release( $release_id ) ) wp_die( 'File non disponibile.', 'File non disponibile', array( 'response' => 404 ) );
	$files = get_post_meta( $release_id, '_trb_release_files', true );
	$file  = is_array( $files ) && isset( $files[ $file_index ] ) ? $files[ $file_index ] : array();
	$uploads = wp_upload_dir();
	$base = realpath( trailingslashit( $uploads['basedir'] ) . 'trb-release-private' );
	$target = ! empty( $file['path'] ) ? realpath( trailingslashit( $uploads['basedir'] ) . ltrim( $file['path'], '/' ) ) : false;
	if ( ! $base || ! $target || 0 !== strpos( $target, $base . DIRECTORY_SEPARATOR ) || ! is_file( $target ) ) wp_die( 'File non disponibile.', 'File non disponibile', array( 'response' => 404 ) );
	nocache_headers();
	header( 'Content-Type: ' . sanitize_mime_type( isset( $file['type'] ) ? $file['type'] : 'application/octet-stream' ) );
	$inline = ! empty( $_GET['view'] ) && isset( $file['kind'] ) && 'cover' === $file['kind'];
	$download_name = isset( $file['kind'] ) && 'audio' === $file['kind'] && ! empty( $file['name'] ) ? $file['name'] : ( isset( $file['original_name'] ) ? $file['original_name'] : $file['name'] );
	header( 'Content-Disposition: ' . ( $inline ? 'inline' : 'attachment' ) . '; filename="' . sanitize_file_name( $download_name ) . '"' );
	header( 'X-Content-Type-Options: nosniff' );
	readfile( $target ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_readfile
	exit;
}
add_action( 'admin_post_trb_portal_release_file', 'trb_portal_serve_release_file' );

function trb_portal_replace_release_file() {
	if ( ! is_user_logged_in() ) auth_redirect();
	$release_id = isset( $_POST['trb_release_id'] ) ? absint( $_POST['trb_release_id'] ) : 0;
	$file_index = isset( $_POST['trb_release_file_index'] ) ? absint( $_POST['trb_release_file_index'] ) : 0;
	check_admin_referer( 'trb_portal_replace_release_file_' . $release_id . '_' . $file_index, 'trb_release_file_nonce' );
	if ( ! trb_portal_current_user_can_access_release( $release_id ) ) wp_die( 'Operazione non consentita.', 'Area Artisti TRB rec', array( 'response' => 403 ) );
	$files = get_post_meta( $release_id, '_trb_release_files', true );
	$old_file = is_array( $files ) && isset( $files[ $file_index ] ) ? $files[ $file_index ] : array();
	$new_upload = trb_portal_release_upload_item( 'trb_release_replacement' );
	$kind = isset( $old_file['kind'] ) ? $old_file['kind'] : '';
	$valid = in_array( $kind, array( 'cover', 'presentation', 'lyrics', 'audio', 'rights_document' ), true ) ? trb_portal_validate_release_upload( $new_upload, $kind ) : new WP_Error( 'invalid_file' );
	if ( 'cover' === $kind && empty( $_POST['trb_release_cover_300dpi'] ) ) $valid = new WP_Error( 'invalid_cover' );
	if ( 'audio' === $kind && ! is_wp_error( $valid ) ) {
		$release_tracks    = (array) get_post_meta( $release_id, '_trb_release_tracks', true );
		$replacement_track = isset( $old_file['track'] ) ? absint( $old_file['track'] ) : 0;
		$declared_seconds  = isset( $release_tracks[ $replacement_track ] ) ? trb_portal_release_track_duration_seconds( $release_tracks[ $replacement_track ] ) : 0;
		$wav_spec          = trb_portal_wav_spec( $new_upload['tmp_name'] );
		if ( is_wp_error( $wav_spec ) || $declared_seconds <= 0 || abs( $wav_spec['duration_seconds'] - $declared_seconds ) > 1.0 ) {
			$valid = new WP_Error( 'audio_duration_mismatch' );
		}
	}
	if ( is_wp_error( $valid ) ) {
		$invalid_status = 'audio_duration_mismatch' === $valid->get_error_code() ? 'duration_mismatch' : 'file_invalid';
		wp_safe_redirect( add_query_arg( 'trb_release', $invalid_status, get_permalink( get_option( 'trb_portal_dashboard_created' ) ) ) . '#release-files-' . $release_id );
		exit;
	}
	$replacement_meta = array();
	if ( 'audio' === $kind ) {
		$release_tracks = (array) get_post_meta( $release_id, '_trb_release_tracks', true );
		$replacement_track = isset( $old_file['track'] ) ? absint( $old_file['track'] ) : 0;
		$replacement_meta = array(
			'track_title' => isset( $release_tracks[ $replacement_track ]['title'] ) ? $release_tracks[ $replacement_track ]['title'] : '',
			'audio_status' => ! empty( $old_file['audio_status'] ) ? $old_file['audio_status'] : 'mastered',
			'replacement' => true,
		);
	}
	$stored = trb_portal_store_release_upload( $release_id, $new_upload, $kind, isset( $old_file['track'] ) ? $old_file['track'] : null, $replacement_meta );
	if ( is_wp_error( $stored ) ) {
		wp_safe_redirect( add_query_arg( 'trb_release', 'file_error', get_permalink( get_option( 'trb_portal_dashboard_created' ) ) ) . '#release-files-' . $release_id );
		exit;
	}
	$security_blocked = false;
	if ( 'audio' !== $kind && function_exists( 'trb_analysis_antivirus_scan' ) ) {
		$local = function_exists( 'trb_release_pcloud_local_file' ) ? trb_release_pcloud_local_file( $stored ) : '';
		$scan = $local ? trb_analysis_antivirus_scan( $local ) : new WP_Error( 'VIRUS_SCAN_FILE_MISSING' );
		$stored['security_status'] = is_wp_error( $scan ) ? $scan->get_error_code() : 'clean';
		$security_blocked = is_wp_error( $scan );
	}
	if ( 'audio' === $kind && ! empty( $old_file['audio_status'] ) ) $stored['audio_status'] = $old_file['audio_status'];
	if ( ! empty( $old_file['path'] ) && $old_file['path'] !== $stored['path'] ) {
		$previous_files = (array) get_post_meta( $release_id, '_trb_release_previous_files', true );
		$previous_files[] = $old_file;
		update_post_meta( $release_id, '_trb_release_previous_files', $previous_files );
	}
	$files[ $file_index ] = $stored;
	update_post_meta( $release_id, '_trb_release_files', array_values( $files ) );
	if ( 'rights_document' === $kind && is_array( $stored ) ) {
		$documents = (array) get_post_meta( $release_id, '_trb_release_rights_documents', true );
		foreach ( $documents as $document_index => $document ) {
			if ( empty( $old_file['sha256'] ) || empty( $document['sha256'] ) || ! hash_equals( (string) $old_file['sha256'], (string) $document['sha256'] ) ) continue;
			$rights_meta = $stored;
			$rights_meta['kind'] = 'rights';
			$rights_meta['status'] = 'pending';
			$rights_meta['uploaded_at'] = time();
			$documents[ $document_index ] = $rights_meta;
			break;
		}
		update_post_meta( $release_id, '_trb_release_rights_documents', array_values( $documents ) );
	}
	if ( $security_blocked ) update_post_meta( $release_id, '_trb_release_pipeline_status', 'security_scan_waiting' );
	elseif ( function_exists( 'trb_release_pcloud_schedule_sync' ) ) trb_release_pcloud_schedule_sync( $release_id, true );
	$staging_session = isset( $_POST['trb_release_submission_token'] ) ? sanitize_text_field( wp_unslash( $_POST['trb_release_submission_token'] ) ) : '';
	if ( $staging_session ) trb_portal_cleanup_release_staging_session( $staging_session );
	wp_safe_redirect( add_query_arg( 'trb_release', 'file_replaced', get_permalink( get_option( 'trb_portal_dashboard_created' ) ) ) . '#release-files-' . $release_id );
	exit;
}
add_action( 'admin_post_trb_portal_replace_release_file', 'trb_portal_replace_release_file' );

/**
 * Finish a release submission without making an AJAX failure look successful.
 * Keeping the browser on the form also keeps every typed value and selected
 * local file available for a corrected retry.
 */
function trb_portal_release_submission_response( $status, $message = '', $http_status = 422, $release_id = 0 ) {
	$status     = sanitize_key( $status );
	$release_id = absint( $release_id );
	$is_success = 'created' === $status;
	$redirect   = add_query_arg( 'trb_release', $status, get_permalink( get_option( 'trb_portal_dashboard_created' ) ) ) . '#release';

	if ( ! $is_success && is_user_logged_in() ) {
		update_user_meta( get_current_user_id(), '_trb_release_last_submission_error', array(
			'code'           => $status,
			'message'        => sanitize_text_field( $message ),
			'http_status'    => absint( $http_status ),
			'content_length' => isset( $_SERVER['CONTENT_LENGTH'] ) ? absint( $_SERVER['CONTENT_LENGTH'] ) : 0,
			'at'             => time(),
		) );
	}

	if ( isset( $_POST['trb_release_ajax'] ) && '1' === sanitize_text_field( wp_unslash( $_POST['trb_release_ajax'] ) ) ) {
		$data = array(
			'status'     => $status,
			'message'    => $message,
			'redirect'   => $redirect,
			'release_id' => $release_id,
		);
		if ( $is_success ) wp_send_json_success( $data, 200 );
		wp_send_json_error( $data, $http_status );
	}

	wp_safe_redirect( $redirect );
	exit;
}

function trb_portal_release_upload_error_message( $code ) {
	$messages = array(
		'missing_cover'              => 'La copertina non è arrivata al server. Selezionala nuovamente e riprova.',
		'invalid_cover'              => 'La copertina non rispetta formato, dimensioni o proporzioni richieste.',
		'missing_presentation'       => 'La presentazione della release non è arrivata al server.',
		'invalid_presentation'       => 'La presentazione deve essere un file TXT, DOCX, ODT o RTF valido fino a 5 MB.',
		'missing_audio'              => 'Il file WAV non è arrivato al server. Controlla dimensione e connessione.',
		'invalid_audio'              => 'Il file audio deve essere un WAV stereo PCM tra 44.100 e 96.000 Hz e tra 16 e 24 bit.',
		'missing_lyrics'             => 'Il testo obbligatorio del brano non è arrivato al server.',
		'invalid_lyrics'             => 'Il testo del brano deve essere un file TXT, DOCX, ODT o RTF valido fino a 5 MB.',
		'audio_duration_mismatch'    => 'La durata indicata non coincide con il WAV: è ammessa una tolleranza massima di 1 secondo.',
		'audio_standard_mismatch'    => 'Tutti i WAV della release devono avere la stessa frequenza di campionamento e profondità in bit.',
		'missing_rights_document'    => 'La licenza obbligatoria non è arrivata al server.',
		'invalid_rights_document'    => 'La licenza deve essere un PDF valido fino a 10 MB.',
		'release_storage_failed'     => 'Il server non è riuscito a trasferire un file dall’area temporanea all’archivio privato.',
		'TEMP_STORAGE_LIMIT_REACHED' => 'Lo spazio temporaneo del server non è sufficiente: la pratica non è stata registrata.',
		'TEMP_STORAGE_UNVERIFIED'    => 'Il server non è riuscito a verificare lo spazio disponibile: la pratica non è stata registrata.',
	);
	return isset( $messages[ $code ] ) ? $messages[ $code ] : 'Uno o più file non rispettano i requisiti indicati. La pratica non è stata registrata.';
}

function trb_portal_start_release() {
	if ( ! is_user_logged_in() ) {
		auth_redirect();
	}

	check_admin_referer( 'trb_portal_start_release', 'trb_portal_release_nonce' );
	if ( ! trb_portal_user_profile() && ! current_user_can( 'manage_options' ) ) {
		trb_portal_release_submission_response( 'profile_required', 'Il tuo profilo non è ancora configurato.', 403 );
	}

	if ( ! trb_portal_artist_profile_is_complete() && ! current_user_can( 'manage_options' ) ) {
		trb_portal_release_submission_response( 'profile_required', 'Completa prima tutti i dati obbligatori del profilo artista.', 422 );
	}
	$user_id = get_current_user_id();
	$profile = trb_portal_user_profile();
	if ( ! current_user_can( 'manage_options' ) && trb_portal_ddb12_limit_reached( $user_id ) ) {
		trb_portal_ddb12_limit_redirect();
	}
	$title = isset( $_POST['trb_release_title'] ) ? sanitize_text_field( wp_unslash( $_POST['trb_release_title'] ) ) : '';
	$type  = isset( $_POST['trb_release_type'] ) ? sanitize_key( wp_unslash( $_POST['trb_release_type'] ) ) : '';
	$types = trb_portal_release_types();
	$is_catalogue = isset( $types[ $type ]['catalogue'] ) && $types[ $type ]['catalogue'];
	$release_state = isset( $_POST['trb_release_state'] ) ? sanitize_key( wp_unslash( $_POST['trb_release_state'] ) ) : '';
	$release_date = isset( $_POST['trb_release_date'] ) ? sanitize_text_field( wp_unslash( $_POST['trb_release_date'] ) ) : '';
	$original_date = isset( $_POST['trb_release_original_date'] ) ? sanitize_text_field( wp_unslash( $_POST['trb_release_original_date'] ) ) : '';
	$tracks = isset( $_POST['trb_tracks'] ) && is_array( $_POST['trb_tracks'] ) ? (array) wp_unslash( $_POST['trb_tracks'] ) : array();
	if ( 'dds' === $profile ) {
		foreach ( $tracks as &$dds_track ) $dds_track['audio_status'] = 'mastered';
		unset( $dds_track );
	}
	$posted_tracks = $tracks;
	$tracks = trb_portal_sanitize_release_tracks( $tracks );
	$minimum_release_date = ( new DateTimeImmutable( 'today', wp_timezone() ) )->modify( '+30 days' )->format( 'Y-m-d' );
	$release_date_valid = false;
	if ( 'unreleased' === $release_state && preg_match( '/^(\\d{4})-(\\d{2})-(\\d{2})$/', $release_date, $release_date_parts ) ) {
		$release_date_valid = checkdate( (int) $release_date_parts[2], (int) $release_date_parts[3], (int) $release_date_parts[1] ) && $release_date >= $minimum_release_date;
	}
	$original_date_valid = false;
	if ( 'previously_released' === $release_state && preg_match( '/^(\\d{4})-(\\d{2})-(\\d{2})$/', $original_date, $date_parts ) ) {
		$original_date_valid = checkdate( (int) $date_parts[2], (int) $date_parts[3], (int) $date_parts[1] ) && $original_date <= wp_date( 'Y-m-d' );
	}
	$cover = trb_portal_release_upload_item( 'trb_release_cover' );
	$presentation = trb_portal_release_upload_item( 'trb_release_presentation' );
	$uploads_valid = trb_portal_validate_release_upload( $cover, 'cover' );
	if ( ! is_wp_error( $uploads_valid ) ) $uploads_valid = trb_portal_validate_release_upload( $presentation, 'presentation' );
	if ( ! is_wp_error( $uploads_valid ) && empty( $_POST['trb_release_cover_300dpi'] ) ) $uploads_valid = new WP_Error( 'invalid_cover' );
	$release_audio_standard = null;
	$rights_documents = array();
	foreach ( $posted_tracks as $track_index => $posted_track ) {
		$advisory = isset( $posted_track['advisory'] ) ? sanitize_key( $posted_track['advisory'] ) : '';
		$audio_status = isset( $posted_track['audio_status'] ) ? sanitize_key( $posted_track['audio_status'] ) : '';
		$audio = trb_portal_release_upload_item( 'trb_track_audio', $track_index );
		$audio_valid = trb_portal_validate_release_upload( $audio, 'audio' );
		if ( is_wp_error( $audio_valid ) || ! in_array( $audio_status, array( 'mastered', 'mastering' ), true ) || ( 'dds' === $profile && 'mastered' !== $audio_status ) ) $uploads_valid = is_wp_error( $audio_valid ) ? $audio_valid : new WP_Error( 'invalid_audio' );
		if ( ! is_wp_error( $audio_valid ) ) {
			$wav_spec = trb_portal_wav_spec( $audio['tmp_name'] );
			$declared_seconds = ( isset( $posted_track['duration_minutes'] ) ? absint( $posted_track['duration_minutes'] ) : 0 ) * 60 + ( isset( $posted_track['duration_seconds'] ) ? absint( $posted_track['duration_seconds'] ) : 0 );
			if ( is_wp_error( $wav_spec ) || $declared_seconds <= 0 || abs( $wav_spec['duration_seconds'] - $declared_seconds ) > 1.0 ) {
				$uploads_valid = new WP_Error( 'audio_duration_mismatch' );
			}
			if ( ! is_wp_error( $wav_spec ) ) {
				$current_standard = array( (int) $wav_spec['sample_rate'], (int) $wav_spec['bit_depth'] );
				if ( null === $release_audio_standard ) $release_audio_standard = $current_standard;
				elseif ( $release_audio_standard !== $current_standard ) $uploads_valid = new WP_Error( 'audio_standard_mismatch' );
			}
		}
		$lyrics = trb_portal_release_upload_item( 'trb_track_lyrics', $track_index );
		if ( 'no_lyrics' !== $advisory ) {
			$lyrics_valid = trb_portal_validate_release_upload( $lyrics, 'lyrics' );
			if ( is_wp_error( $lyrics_valid ) ) $uploads_valid = $lyrics_valid;
		} elseif ( ! empty( $lyrics['name'] ) ) {
			$lyrics_valid = trb_portal_validate_release_upload( $lyrics, 'lyrics' );
			if ( is_wp_error( $lyrics_valid ) ) $uploads_valid = $lyrics_valid;
		}
		$nature = isset( $posted_track['content_nature'] ) ? sanitize_key( $posted_track['content_nature'] ) : '';
		$rights_basis = isset( $posted_track['rights_basis'] ) ? sanitize_key( $posted_track['rights_basis'] ) : '';
		$requires_rights_document = 'type_beat' === $nature || 'protected_samples' === $nature || ( 'remix' === $nature && 'licensed' === $rights_basis );
		if ( $requires_rights_document ) {
			$rights_document = trb_portal_release_upload_item( 'trb_track_rights_document', $track_index );
			$rights_valid = trb_portal_validate_release_upload( $rights_document, 'rights_document' );
			if ( is_wp_error( $rights_valid ) ) {
				$uploads_valid = $rights_valid;
			} else {
				$rights_documents[ $track_index ] = $rights_document;
				if ( isset( $tracks[ $track_index ] ) ) $tracks[ $track_index ]['rights_document'] = sanitize_file_name( $rights_document['name'] );
			}
		}
	}
	if ( 'previously_released' === $release_state ) {
		$seen_isrc = array();
		$posted_isrc = isset( $_POST['trb_existing_isrc'] ) ? (array) wp_unslash( $_POST['trb_existing_isrc'] ) : array();
		foreach ( $tracks as $track_index => &$clean_track ) {
			$isrc = isset( $posted_isrc[ $track_index ] ) ? strtoupper( preg_replace( '/[^A-Z0-9]/i', '', (string) $posted_isrc[ $track_index ] ) ) : '';
			if ( ! preg_match( '/^[A-Z]{2}[A-Z0-9]{3}[0-9]{7}$/', $isrc ) || isset( $seen_isrc[ $isrc ] ) ) trb_portal_release_submission_response( 'invalid', 'Inserisci per ogni brano già pubblicato un ISRC valido e non duplicato.', 422 );
			$clean_track['isrc'] = $isrc;
			$seen_isrc[ $isrc ] = true;
		}
		unset( $clean_track );
	}
	$single_title_mismatch = 'single' === $type && '' !== $title && 1 === count( $tracks ) && $title !== $tracks[0]['title'];
	if ( $single_title_mismatch ) {
		trb_portal_release_submission_response( 'single_title_mismatch', 'Per un singolo, il titolo della release deve coincidere esattamente con il titolo del brano.', 422 );
	}
	if ( ! isset( $types[ $type ] ) ) trb_portal_release_submission_response( 'invalid', 'Seleziona una tipologia di pubblicazione valida.', 422 );
	if ( ! $is_catalogue && '' === $title ) trb_portal_release_submission_response( 'invalid', 'Inserisci il titolo della release.', 422 );
	if ( empty( $posted_tracks ) || empty( $tracks ) || count( $tracks ) !== count( $posted_tracks ) ) trb_portal_release_submission_response( 'invalid', 'Uno o più brani hanno metadati, generi, autori o crediti mancanti o non validi.', 422 );
	if ( count( $tracks ) < $types[ $type ]['min'] || count( $tracks ) > $types[ $type ]['max'] ) trb_portal_release_submission_response( 'invalid', 'Il numero di brani non corrisponde alla tipologia di pubblicazione selezionata.', 422 );
	if ( ! in_array( $release_state, array( 'unreleased', 'previously_released' ), true ) ) trb_portal_release_submission_response( 'invalid', 'Seleziona lo stato della pubblicazione.', 422 );
	if ( 'unreleased' === $release_state && ! $release_date_valid ) trb_portal_release_submission_response( 'invalid', 'Scegli una data di uscita non inferiore a 30 giorni da oggi.', 422 );
	if ( 'previously_released' === $release_state && ! $original_date_valid ) trb_portal_release_submission_response( 'invalid', 'Inserisci una data di pubblicazione originale valida e non futura.', 422 );
	if ( $is_catalogue && 'previously_released' !== $release_state ) trb_portal_release_submission_response( 'invalid', 'Un catalogo o repertorio edito deve essere indicato come già pubblicato.', 422 );
	if ( is_wp_error( $uploads_valid ) ) {
		$upload_code = $uploads_valid->get_error_code();
		trb_portal_release_submission_response( 'audio_duration_mismatch' === $upload_code ? 'duration_mismatch' : 'invalid', trb_portal_release_upload_error_message( $upload_code ), 422 );
	}
	if ( $is_catalogue && '' === $title ) {
		$title = 'Catalogo / repertorio edito';
	}

	// The unique monthly marker closes the short race window caused by two tabs
	// submitting at the same time. The post query also covers practices created
	// before this feature was introduced.
	$ddb12_reservation_key   = '';
	$ddb12_reservation_value = '';
	if ( 'ddb12' === $profile && ! current_user_can( 'manage_options' ) ) {
		$ddb12_reservation_key   = '_trb_ddb12_release_' . wp_date( 'Y_m' );
		$ddb12_reservation_value = (string) time();
		$existing_reservation    = (string) get_user_meta( $user_id, $ddb12_reservation_key, true );
		if ( $existing_reservation && ctype_digit( $existing_reservation ) && ( time() - (int) $existing_reservation ) > 900 && 0 === trb_portal_ddb12_monthly_release_count( $user_id ) ) {
			delete_user_meta( $user_id, $ddb12_reservation_key );
		}
		if ( trb_portal_ddb12_monthly_release_count( $user_id ) >= 1 || ! add_user_meta( $user_id, $ddb12_reservation_key, $ddb12_reservation_value, true ) ) {
			trb_portal_ddb12_limit_redirect();
		}
	}
	$submit_lock_key = '_trb_release_submission_lock';
	$existing_submit_lock = absint( get_user_meta( $user_id, $submit_lock_key, true ) );
	if ( $existing_submit_lock && time() - $existing_submit_lock > 30 * MINUTE_IN_SECONDS ) delete_user_meta( $user_id, $submit_lock_key );
	if ( ! add_user_meta( $user_id, $submit_lock_key, time(), true ) ) {
		trb_portal_release_submission_response( 'upload_in_progress', 'Una richiesta precedente è ancora in elaborazione. Attendi senza inviare nuovamente i file.', 409 );
	}
	$submission_token = isset( $_POST['trb_release_submission_token'] ) ? sanitize_text_field( wp_unslash( $_POST['trb_release_submission_token'] ) ) : '';
	if ( $submission_token ) {
		$existing_release = get_posts( array(
			'post_type'      => 'trb_release',
			'post_status'    => array( 'publish', 'private', 'pending', 'draft' ),
			'author'         => $user_id,
			'posts_per_page' => 1,
			'fields'         => 'ids',
			'meta_key'       => '_trb_release_submission_token',
			'meta_value'     => $submission_token,
		) );
		if ( $existing_release ) {
			delete_user_meta( $user_id, $submit_lock_key );
			trb_portal_cleanup_release_staging_session( $submission_token );
			trb_portal_release_submission_response( 'created', 'La pratica era già stata registrata: non è stato creato alcun duplicato.', 200, $existing_release[0] );
		}
	}

	$release_id = wp_insert_post(
		array(
			'post_type'   => 'trb_release',
			'post_status' => 'publish',
			'post_title'  => $title,
			'post_author' => get_current_user_id(),
		)
	);
	if ( $release_id && ! is_wp_error( $release_id ) ) {
		$release_files = array();
		$stored_rights_documents = array();
		$release_files[] = trb_portal_store_release_upload( $release_id, $cover, 'cover' );
		$release_files[] = trb_portal_store_release_upload( $release_id, $presentation, 'presentation' );
		foreach ( $posted_tracks as $track_index => $posted_track ) {
			$audio = trb_portal_release_upload_item( 'trb_track_audio', $track_index );
			$audio_status = isset( $posted_track['audio_status'] ) ? sanitize_key( $posted_track['audio_status'] ) : 'mastered';
			$stored_audio = trb_portal_store_release_upload( $release_id, $audio, 'audio', $track_index, array( 'track_title' => isset( $posted_track['title'] ) ? sanitize_text_field( $posted_track['title'] ) : '', 'audio_status' => $audio_status ) );
			if ( is_array( $stored_audio ) ) $stored_audio['audio_status'] = isset( $posted_track['audio_status'] ) ? sanitize_key( $posted_track['audio_status'] ) : 'mastered';
			$release_files[] = $stored_audio;
			$lyrics = trb_portal_release_upload_item( 'trb_track_lyrics', $track_index );
			if ( ! empty( $lyrics['name'] ) ) $release_files[] = trb_portal_store_release_upload( $release_id, $lyrics, 'lyrics', $track_index );
			if ( isset( $rights_documents[ $track_index ] ) ) {
				$stored_rights = trb_portal_store_release_upload( $release_id, $rights_documents[ $track_index ], 'rights_document', $track_index );
				$release_files[] = $stored_rights;
				if ( is_array( $stored_rights ) ) {
					$rights_meta = $stored_rights;
					$rights_meta['kind'] = 'rights';
					$rights_meta['status'] = 'pending';
					$rights_meta['uploaded_at'] = time();
					$stored_rights_documents[] = $rights_meta;
				}
			}
		}
		$file_error = null;
		foreach ( $release_files as $file ) if ( is_wp_error( $file ) && ! $file_error ) $file_error = $file;
		if ( $file_error ) {
			$stored_files = array_values( array_filter( $release_files, 'is_array' ) );
			update_post_meta( $release_id, '_trb_release_type', $type );
			update_post_meta( $release_id, '_trb_release_state', $release_state );
			update_post_meta( $release_id, '_trb_release_date', 'unreleased' === $release_state ? $release_date : '' );
			update_post_meta( $release_id, '_trb_release_original_date', 'previously_released' === $release_state ? $original_date : '' );
			update_post_meta( $release_id, '_trb_release_tracks', $tracks );
			update_post_meta( $release_id, '_trb_release_files', $stored_files );
			update_post_meta( $release_id, '_trb_release_pipeline_status', 'upload_failed' );
			update_post_meta( $release_id, '_trb_contract_state', 'upload_failed' );
			if ( $submission_token ) update_post_meta( $release_id, '_trb_release_submission_token', $submission_token );
			wp_update_post( array( 'ID' => $release_id, 'post_status' => 'private' ) );
			if ( $ddb12_reservation_key ) delete_user_meta( $user_id, $ddb12_reservation_key );
			delete_user_meta( $user_id, $submit_lock_key );
			if ( $submission_token ) trb_portal_cleanup_release_staging_session( $submission_token );
			trb_portal_release_submission_response( 'error', 'I dati della pratica sono stati conservati, ma uno o più file non sono stati archiviati. Causa: ' . trb_portal_release_upload_error_message( $file_error->get_error_code() ) . ' Non reinviare tutto: la pratica è visibile e può essere completata.', 500, $release_id );
		}
		if ( 'trb' === $profile && 'unreleased' === $release_state ) {
			$assigned_isrcs = function_exists( 'trb_release_bridge_allocate_isrcs' ) ? trb_release_bridge_allocate_isrcs( count( $tracks ) ) : new WP_Error( 'isrc_allocator_missing' );
			if ( is_wp_error( $assigned_isrcs ) || count( $assigned_isrcs ) !== count( $tracks ) ) {
				update_post_meta( $release_id, '_trb_release_type', $type );
				update_post_meta( $release_id, '_trb_release_state', $release_state );
				update_post_meta( $release_id, '_trb_release_date', $release_date );
				update_post_meta( $release_id, '_trb_release_tracks', $tracks );
				update_post_meta( $release_id, '_trb_release_files', array_values( array_filter( $release_files, 'is_array' ) ) );
				update_post_meta( $release_id, '_trb_release_pipeline_status', 'isrc_assignment_failed' );
				update_post_meta( $release_id, '_trb_contract_state', 'data_error' );
				if ( $submission_token ) update_post_meta( $release_id, '_trb_release_submission_token', $submission_token );
				wp_update_post( array( 'ID' => $release_id, 'post_status' => 'private' ) );
				if ( $ddb12_reservation_key ) delete_user_meta( $user_id, $ddb12_reservation_key );
				delete_user_meta( $user_id, $submit_lock_key );
				if ( $submission_token ) trb_portal_cleanup_release_staging_session( $submission_token );
				trb_portal_release_submission_response( 'error', 'La pratica e i file sono stati conservati, ma il sistema non ha potuto assegnare gli ISRC. Nessun codice è stato mostrato o riutilizzato.', 500, $release_id );
			}
			foreach ( $tracks as $track_index => &$track ) $track['isrc'] = $assigned_isrcs[ $track_index ];
			unset( $track );
		}
		if ( $ddb12_reservation_key ) {
			update_user_meta( $user_id, $ddb12_reservation_key, (string) $release_id );
		}
		update_post_meta( $release_id, '_trb_release_type', $type );
		update_post_meta( $release_id, '_trb_release_step', 'contract' );
		update_post_meta( $release_id, '_trb_release_status', 'artist_action' );
		update_post_meta( $release_id, '_trb_release_state', $release_state );
		update_post_meta( $release_id, '_trb_release_date', 'unreleased' === $release_state ? $release_date : '' );
		update_post_meta( $release_id, '_trb_release_original_date', 'previously_released' === $release_state ? $original_date : '' );
		update_post_meta( $release_id, '_trb_release_tracks', $tracks );
		if ( $submission_token ) update_post_meta( $release_id, '_trb_release_submission_token', $submission_token );
		update_post_meta( $release_id, '_trb_release_rights_declarations', array_map( static function ( $track ) { return array( 'nature' => $track['content_nature'], 'basis' => $track['rights_basis'], 'reference' => isset( $track['rights_reference'] ) ? $track['rights_reference'] : '' ); }, $tracks ) );
		if ( $stored_rights_documents ) update_post_meta( $release_id, '_trb_release_rights_documents', $stored_rights_documents );
		$security_blocked = false;
		if ( function_exists( 'trb_analysis_antivirus_scan' ) ) foreach ( $release_files as &$release_file ) {
			if ( ! is_array( $release_file ) || 'audio' === ( $release_file['kind'] ?? '' ) ) continue;
			$local = function_exists( 'trb_release_pcloud_local_file' ) ? trb_release_pcloud_local_file( $release_file ) : '';
			$scan = $local ? trb_analysis_antivirus_scan( $local ) : new WP_Error( 'VIRUS_SCAN_FILE_MISSING' );
			$release_file['security_status'] = is_wp_error( $scan ) ? $scan->get_error_code() : 'clean';
			if ( is_wp_error( $scan ) ) $security_blocked = true;
		}
		unset( $release_file );
		update_post_meta( $release_id, '_trb_release_files', $release_files );
		if ( $security_blocked ) {
			update_post_meta( $release_id, '_trb_release_pipeline_status', 'security_scan_waiting' );
			if ( function_exists( 'trb_resource_event' ) ) trb_resource_event( 'release-' . $release_id, 'security', 'critical', 'Materiali conservati nello storage privato in attesa di scansione antivirus.', array( 'release_id' => $release_id ) );
		} elseif ( function_exists( 'trb_release_pcloud_schedule_sync' ) ) trb_release_pcloud_schedule_sync( $release_id );
		delete_user_meta( $user_id, $submit_lock_key );
		if ( $submission_token ) trb_portal_cleanup_release_staging_session( $submission_token );
		trb_portal_release_submission_response( 'created', 'Pratica creata correttamente.', 200, $release_id );
	}
	if ( $ddb12_reservation_key ) {
		delete_user_meta( $user_id, $ddb12_reservation_key, $ddb12_reservation_value );
	}
	delete_user_meta( $user_id, $submit_lock_key );

	trb_portal_release_submission_response( 'error', 'Il server non è riuscito a creare la pratica. I dati compilati sono ancora presenti nel modulo.', 500 );
}
add_action( 'admin_post_trb_portal_start_release', 'trb_portal_start_release' );

function trb_portal_sanitize_contributors( $rows, $allowed_roles ) {
	$clean = array();
	foreach ( (array) $rows as $row ) {
		$name = isset( $row['name'] ) ? sanitize_text_field( $row['name'] ) : '';
		$role = isset( $row['role'] ) ? sanitize_text_field( $row['role'] ) : '';
		if ( '' !== $name && isset( $allowed_roles[ $role ] ) ) {
			$clean[] = array( 'name' => $name, 'role' => $role );
		}
	}
	return $clean;
}

function trb_portal_sanitize_writers( $rows ) {
	$clean = array();
	foreach ( (array) $rows as $row ) {
		$name       = isset( $row['name'] ) ? sanitize_text_field( $row['name'] ) : '';
		$roles      = isset( $row['roles'] ) ? array_map( 'sanitize_text_field', (array) $row['roles'] ) : array();
		$roles      = array_values( array_intersect( array( 'Lyricist', 'Composer' ), array_unique( $roles ) ) );
		if ( '' !== $name && ! empty( $roles ) ) {
			$clean[] = array( 'name' => $name, 'roles' => $roles, 'role' => implode( ', ', $roles ) );
		}
	}
	$count = count( $clean );
	if ( $count ) {
		$base      = intdiv( 10000, $count );
		$remainder = 10000 - ( $base * $count );
		foreach ( $clean as $index => &$writer ) {
			$writer['share'] = number_format( ( $base + ( $index < $remainder ? 1 : 0 ) ) / 100, 2, '.', '' );
		}
		unset( $writer );
	}
	return $clean;
}

function trb_portal_sanitize_release_tracks( $tracks ) {
	$genres    = trb_portal_genres();
	$roles     = trb_portal_contributor_roles();
	$clean     = array();
	foreach ( $tracks as $track ) {
		$title   = isset( $track['title'] ) ? sanitize_text_field( $track['title'] ) : '';
		$credits = isset( $track['credits'] ) && is_array( $track['credits'] ) ? $track['credits'] : array();
		$minutes = isset( $track['duration_minutes'] ) ? absint( $track['duration_minutes'] ) : null;
		$seconds = isset( $track['duration_seconds'] ) ? absint( $track['duration_seconds'] ) : null;
		$duration = ( null !== $minutes && null !== $seconds && $minutes <= 19 && $seconds <= 59 )
			? sprintf( '%02d:%02d', $minutes, $seconds )
			: ( isset( $track['duration'] ) ? sanitize_text_field( $track['duration'] ) : '' );
		$primary   = isset( $track['primary_genre'] ) ? sanitize_text_field( $track['primary_genre'] ) : '';
		$secondary = isset( $track['secondary_genre'] ) ? sanitize_text_field( $track['secondary_genre'] ) : '';
		$writers   = trb_portal_sanitize_writers( isset( $credits['writers'] ) ? $credits['writers'] : array() );
		$additional_credits = trb_portal_sanitize_contributors( isset( $credits['credits'] ) ? $credits['credits'] : array(), $roles['credits'] );
		$nature = isset( $track['content_nature'] ) ? sanitize_key( $track['content_nature'] ) : '';
		$rights_basis = isset( $track['rights_basis'] ) ? sanitize_key( $track['rights_basis'] ) : '';
		$allowed_rights = array( 'original' => array( 'owned' ), 'type_beat' => array( 'exclusive', 'nonexclusive' ), 'remix' => array( 'licensed' ), 'protected_samples' => array( 'licensed' ) );
		if (
			'' === $title || '00:00' === $duration || ! preg_match( '/^[0-9]{2}:[0-5][0-9]$/', $duration ) ||
			! in_array( $primary, $genres, true ) || ( '' !== $secondary && ( $secondary === $primary || ! in_array( $secondary, $genres, true ) ) ) ||
			empty( $writers ) || empty( $additional_credits ) || ! isset( $allowed_rights[ $nature ] ) || ! in_array( $rights_basis, $allowed_rights[ $nature ], true )
		) {
			continue;
		}
		$advisory = isset( $track['advisory'] ) ? sanitize_key( $track['advisory'] ) : '';
		if ( ! in_array( $advisory, array( 'no_lyrics', 'non_explicit', 'clean', 'explicit' ), true ) ) continue;
		$summary = static function ( $contributors ) {
			return implode( "\n", array_map( static function ( $entry ) { return $entry['name'] . ' — ' . $entry['role'] . ( isset( $entry['share'] ) ? ' — ' . $entry['share'] . '%' : '' ); }, $contributors ) );
		};
		$writer_summary = static function ( $contributors, $role ) {
			return implode( "\n", array_map( static function ( $entry ) { return $entry['name'] . ' — ' . $entry['share'] . '%'; }, array_filter( $contributors, static function ( $entry ) use ( $role ) { return in_array( $role, $entry['roles'], true ); } ) ) );
		};
		$clean[] = array(
			'title' => $title,
			'version' => isset( $track['version'] ) ? sanitize_text_field( $track['version'] ) : '',
			'featuring' => isset( $track['featuring'] ) ? sanitize_text_field( $track['featuring'] ) : '',
			'duration' => $duration,
			'advisory' => $advisory,
			'primary_genre' => $primary,
			'secondary_genre' => $secondary,
			'audio_status' => isset( $track['audio_status'] ) ? sanitize_key( $track['audio_status'] ) : '',
			'content_nature' => $nature,
			'rights_basis' => $rights_basis,
			'rights_reference' => '',
			'credits' => array(
				'writers' => $writers, 'credits' => $additional_credits,
				'authors' => $writer_summary( $writers, 'Lyricist' ), 'composers' => $writer_summary( $writers, 'Composer' ),
				'performers_legacy' => $summary( $additional_credits ), 'producers' => $summary( $additional_credits ),
				'musicians' => $summary( $additional_credits ),
			),
		);
	}
	return array_values( $clean );
}

/**
 * Canonical answers are maintained once here, rather than duplicated across
 * the old contract-specific FAQ homes.
