		),
	);
	foreach ( $revisions as $package_id => $revision ) {
		if ( 'wpdmpro' === get_post_type( $package_id ) ) {
			wp_update_post( array_merge( array( 'ID' => $package_id ), $revision ) );
		}
	}

	update_option( 'trb_portal_download_audience_migrated_v2', time(), false );
}
