/**
 * Add working hours without making the artist receive an automated review at
 * night or during the weekend. Working time is Monday-Friday, 09:00-19:00,
 * in the WordPress timezone.
 */
function trb_portal_add_demo_working_hours( $submitted_at, $hours = 4 ) {
	$timezone = wp_timezone();
	$current  = ( new DateTimeImmutable( '@' . (int) $submitted_at ) )->setTimezone( $timezone );
	$remaining_minutes = max( 1, (int) $hours ) * 60;

	while ( $remaining_minutes > 0 ) {
		$weekday = (int) $current->format( 'N' );
		if ( $weekday > 5 ) {
			$current = $current->modify( 'next monday' )->setTime( 9, 0 );
			continue;
		}
		$opening = $current->setTime( 9, 0 );
		$closing = $current->setTime( 19, 0 );
		if ( $current < $opening ) $current = $opening;
		if ( $current >= $closing ) {
			$current = $current->modify( '+1 day' )->setTime( 9, 0 );
			continue;
		}
		$available = (int) floor( ( $closing->getTimestamp() - $current->getTimestamp() ) / 60 );
		$step = min( $remaining_minutes, $available );
		$current = $current->modify( '+' . $step . ' minutes' );
		$remaining_minutes -= $step;
	}

	return $current->getTimestamp();
}

function trb_portal_store_demo_file( $input, $mimes, $max_bytes ) {
	if ( empty( $_FILES[ $input ]['name'] ) || empty( $_FILES[ $input ]['tmp_name'] ) ) return null;
	$file = $_FILES[ $input ]; // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized
	if ( UPLOAD_ERR_OK !== (int) $file['error'] || (int) $file['size'] > $max_bytes ) return new WP_Error( 'invalid_upload' );
	if ( function_exists( 'trb_resource_temp_storage_guard' ) ) {
		$storage_guard = trb_resource_temp_storage_guard( (int) $file['size'] );
		if ( is_wp_error( $storage_guard ) ) return $storage_guard;
	}
	require_once ABSPATH . 'wp-admin/includes/file.php';
	$file['name'] = sanitize_file_name( $file['name'] );
	$uploads = wp_upload_dir();
	if ( ! empty( $uploads['error'] ) ) return new WP_Error( 'upload_directory_unavailable', $uploads['error'] );
	$private_dir = trailingslashit( $uploads['basedir'] ) . 'trb-demo-private';
	if ( ! wp_mkdir_p( $private_dir ) || ! is_dir( $private_dir ) || ! is_writable( $private_dir ) ) {
		return new WP_Error( 'upload_directory_unavailable', 'La cartella privata dei demo non è disponibile in scrittura.' );
	}
	$rules = trailingslashit( $private_dir ) . '.htaccess';
	if ( ! file_exists( $rules ) ) file_put_contents( $rules, "Require all denied\nDeny from all\nOptions -Indexes\n" ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_file_put_contents
	add_filter( 'upload_dir', 'trb_portal_demo_upload_dir', 99 );
	$handled = wp_handle_upload( $file, array( 'test_form' => false, 'mimes' => $mimes ) );
	remove_filter( 'upload_dir', 'trb_portal_demo_upload_dir', 99 );
	if ( ! empty( $handled['error'] ) || empty( $handled['file'] ) ) return new WP_Error( 'invalid_upload', ! empty( $handled['error'] ) ? $handled['error'] : 'WordPress non ha salvato il file caricato.' );
	return array( 'name' => basename( $handled['file'] ), 'path' => str_replace( trailingslashit( $uploads['basedir'] ), '', $handled['file'] ), 'type' => $handled['type'], 'size' => (int) $file['size'] );
}

function trb_portal_demo_finish( $status, $dashboard, $success = false ) {
	$redirect = 'forbidden' === $status ? $dashboard : add_query_arg( 'trb_demo', $status, $dashboard ) . '#demo';
	$is_async = ( isset( $_SERVER['HTTP_X_TRB_UPLOAD'] ) && '1' === sanitize_text_field( wp_unslash( $_SERVER['HTTP_X_TRB_UPLOAD'] ) ) )
		|| ( isset( $_POST['trb_demo_async'] ) && '1' === sanitize_text_field( wp_unslash( $_POST['trb_demo_async'] ) ) );
	if ( $is_async ) {
		while ( ob_get_level() ) ob_end_clean();
		nocache_headers();
		wp_send_json( array( 'success' => (bool) $success, 'status' => $status, 'redirect' => $redirect ), 200 );
	}
	wp_safe_redirect( $redirect );
	exit;
}

function trb_portal_submit_demo() {
	if ( ! is_user_logged_in() ) auth_redirect();
	$user_id = get_current_user_id();
	$user = wp_get_current_user();
	$dashboard = get_permalink( get_option( 'trb_portal_dashboard_created' ) );
	$nonce = isset( $_POST['trb_demo_nonce'] ) ? sanitize_text_field( wp_unslash( $_POST['trb_demo_nonce'] ) ) : '';
	if ( ! wp_verify_nonce( $nonce, 'trb_portal_submit_demo' ) ) {
		trb_portal_demo_finish( 'session_expired', $dashboard );
	}
	if ( 'dds' === trb_portal_user_profile( $user ) ) {
		trb_portal_demo_finish( 'forbidden', $dashboard );
	}
	$is_test_account = trb_portal_is_demo_test_account( $user );
	$last = (int) get_user_meta( $user_id, '_trb_demo_last_submission', true );
	if ( ! $is_test_account && $last && time() - $last < WEEK_IN_SECONDS ) {
		trb_portal_demo_finish( 'weekly_limit', $dashboard );
	}
	$title = isset( $_POST['trb_demo_title'] ) ? sanitize_text_field( wp_unslash( $_POST['trb_demo_title'] ) ) : '';
	$no_lyrics = isset( $_POST['trb_demo_no_lyrics'] );
	$text_only = isset( $_POST['trb_demo_text_only'] );
	$has_text = ! empty( $_FILES['trb_demo_text']['name'] );
	$has_audio = ! empty( $_FILES['trb_demo_audio']['name'] );
	$valid = '' !== $title && ( $has_text || $has_audio ) && ! ( $no_lyrics && $text_only ) && ( $has_text || $no_lyrics ) && ( $has_audio || $text_only );
	if ( ! $valid ) {
		trb_portal_demo_finish( 'invalid', $dashboard );
	}

	// Atomic server-side lock: browser retries or repeated clicks cannot create
	// simultaneous practices while the first upload is still being processed.
	$lock_key = '_trb_demo_submission_lock';
	$lock_time = (int) get_user_meta( $user_id, $lock_key, true );
	if ( $lock_time && time() - $lock_time < 15 * MINUTE_IN_SECONDS ) {
		trb_portal_demo_finish( 'processing', $dashboard );
	}
	if ( $lock_time ) delete_user_meta( $user_id, $lock_key );
	if ( ! add_user_meta( $user_id, $lock_key, time(), true ) ) {
		trb_portal_demo_finish( 'processing', $dashboard );
	}

	$fingerprint = hash( 'sha256', strtolower( $title ) . '|' . ( $no_lyrics ? '1' : '0' ) . '|' . ( $text_only ? '1' : '0' ) . '|' . ( $has_text ? sanitize_file_name( wp_unslash( $_FILES['trb_demo_text']['name'] ) ) . ':' . (int) $_FILES['trb_demo_text']['size'] : '-' ) . '|' . ( $has_audio ? sanitize_file_name( wp_unslash( $_FILES['trb_demo_audio']['name'] ) ) . ':' . (int) $_FILES['trb_demo_audio']['size'] : '-' ) );
	$previous = get_user_meta( $user_id, '_trb_demo_last_fingerprint', true );
	if ( is_array( $previous ) && ! empty( $previous['hash'] ) && hash_equals( (string) $previous['hash'], $fingerprint ) && time() - (int) $previous['time'] < 10 * MINUTE_IN_SECONDS ) {
		delete_user_meta( $user_id, $lock_key );
		trb_portal_demo_finish( 'duplicate', $dashboard, true );
	}

	$text = trb_portal_store_demo_file( 'trb_demo_text', array( 'txt' => 'text/plain', 'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' ), 2 * MB_IN_BYTES );
	$audio = trb_portal_store_demo_file( 'trb_demo_audio', array( 'mp3' => 'audio/mpeg' ), 25 * MB_IN_BYTES );
	if ( is_wp_error( $text ) || is_wp_error( $audio ) ) {
		foreach ( array( $text, $audio ) as $stored ) if ( is_array( $stored ) && ! empty( $stored['path'] ) ) { $uploads = wp_upload_dir(); wp_delete_file( trailingslashit( $uploads['basedir'] ) . ltrim( $stored['path'], '/' ) ); }
		delete_user_meta( $user_id, $lock_key );
		trb_portal_demo_finish( 'upload_error', $dashboard );
	}
	$request_id = wp_insert_post( array( 'post_type' => 'trb_request', 'post_status' => 'private', 'post_title' => '[Demo] ' . $title, 'post_author' => $user_id ) );
	if ( ! $request_id || is_wp_error( $request_id ) ) {
		foreach ( array( $text, $audio ) as $stored ) if ( is_array( $stored ) && ! empty( $stored['path'] ) ) { $uploads = wp_upload_dir(); wp_delete_file( trailingslashit( $uploads['basedir'] ) . ltrim( $stored['path'], '/' ) ); }
		delete_user_meta( $user_id, $lock_key );
		trb_portal_demo_finish( 'upload_error', $dashboard );
	}
	$submitted_timestamp = time();
	$earliest_delivery   = $is_test_account ? $submitted_timestamp + MINUTE_IN_SECONDS : trb_portal_add_demo_working_hours( $submitted_timestamp, 4 );
	$payload = array(
		'uuid' => wp_generate_uuid4(), 'submitted_at' => gmdate( 'c', $submitted_timestamp ), 'status' => 'queued',
		'earliest_delivery_at' => gmdate( 'c', $earliest_delivery ),
		'first_name' => $user->first_name, 'last_name' => $user->last_name,
		'artist_name' => trb_portal_artist_profile_value( 'artist_name', $user_id ), 'email' => $user->user_email,
		'profile' => trb_portal_user_profile( $user ), 'title' => $title, 'no_lyrics' => $no_lyrics,
		'text_only' => $text_only, 'text_file' => $text, 'audio_file' => $audio,
	);
	update_post_meta( $request_id, '_trb_demo_payload', $payload );
	update_post_meta( $request_id, '_trb_demo_earliest_delivery', $earliest_delivery );
	update_post_meta( $request_id, '_trb_demo_delete_after', $submitted_timestamp + 60 * DAY_IN_SECONDS );
	if ( ! $is_test_account ) update_user_meta( $user_id, '_trb_demo_last_submission', $submitted_timestamp );
	update_user_meta( $user_id, '_trb_demo_last_fingerprint', array( 'hash' => $fingerprint, 'time' => $submitted_timestamp, 'request_id' => $request_id ) );
	delete_user_meta( $user_id, $lock_key );
	wp_schedule_single_event( time() + 10, 'trb_portal_process_demo', array( $request_id ) );
	trb_portal_demo_finish( 'sent', $dashboard, true );
}
add_action( 'admin_post_trb_portal_submit_demo', 'trb_portal_submit_demo' );
add_action( 'wp_ajax_trb_portal_submit_demo', 'trb_portal_submit_demo' );

function trb_portal_render_release_files( $release_id ) {
	$files  = get_post_meta( $release_id, '_trb_release_files', true );
	$tracks = get_post_meta( $release_id, '_trb_release_tracks', true );
	if ( ! is_array( $files ) || empty( $files ) ) return;
	?><div class="trb-release-files" id="release-files-<?php echo esc_attr( $release_id ); ?>"><h4>Materiali caricati</h4><div class="trb-release-files__list"><?php foreach ( $files as $index => $file ) :
		$kind = isset( $file['kind'] ) ? $file['kind'] : '';
		$label = 'cover' === $kind ? 'Copertina' : ( 'presentation' === $kind ? 'Presentazione della release' : ( 'audio' === $kind ? 'File audio del brano' : ( 'rights_document' === $kind ? 'Licenza o autorizzazione del brano' : 'Testo del brano' ) ) );
		if ( in_array( $kind, array( 'lyrics', 'audio', 'rights_document' ), true ) && isset( $file['track'] ) && isset( $tracks[ $file['track'] ]['title'] ) ) $label .= ' “' . $tracks[ $file['track'] ]['title'] . '”';
		$accept = 'cover' === $kind ? 'image/jpeg,image/png,.jpg,.jpeg,.png' : ( 'audio' === $kind ? '.wav,audio/wav,audio/x-wav' : ( 'rights_document' === $kind ? '.pdf,application/pdf' : '.txt,.docx,.odt,.rtf,text/plain,application/rtf,text/rtf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.oasis.opendocument.text' ) );
		?><article class="trb-release-file"><?php if ( 'cover' === $kind ) : ?><img src="<?php echo esc_url( trb_portal_release_file_url( $release_id, $index, true ) ); ?>" alt="Copertina della release" loading="lazy" /><?php endif; ?><div class="trb-release-file__details"><strong><?php echo esc_html( $label ); ?></strong><span><?php echo esc_html( 'audio' === $kind && ! empty( $file['name'] ) ? $file['name'] : ( isset( $file['original_name'] ) ? $file['original_name'] : $file['name'] ) ); ?></span><?php if ( 'audio' === $kind && ! empty( $file['audio_spec'] ) ) : ?><small><?php echo esc_html( number_format_i18n( $file['audio_spec']['sample_rate'], 0 ) . ' Hz · ' . $file['audio_spec']['bit_depth'] . ' bit · ' . ( ! empty( $file['audio_status'] ) && 'mastering' === $file['audio_status'] ? 'mastering richiesto' : 'master' ) ); ?></small><?php endif; ?><a href="<?php echo esc_url( trb_portal_release_file_url( $release_id, $index ) ); ?>">Scarica il file</a><details><summary>Sostituisci</summary><form method="post" enctype="multipart/form-data" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="trb_portal_replace_release_file" /><input type="hidden" name="trb_release_submission_token" value="<?php echo esc_attr( wp_generate_uuid4() ); ?>" /><input type="hidden" name="trb_release_stage_nonce" value="<?php echo esc_attr( wp_create_nonce( 'trb_portal_stage_release' ) ); ?>" /><input type="hidden" name="trb_release_id" value="<?php echo esc_attr( $release_id ); ?>" /><input type="hidden" name="trb_release_file_index" value="<?php echo esc_attr( $index ); ?>" /><?php wp_nonce_field( 'trb_portal_replace_release_file_' . $release_id . '_' . $index, 'trb_release_file_nonce' ); ?><input type="file" name="trb_release_replacement" accept="<?php echo esc_attr( $accept ); ?>" required /><?php if ( 'cover' === $kind ) : ?><label><input type="checkbox" name="trb_release_cover_300dpi" value="1" required /> Confermo 300 DPI</label><?php elseif ( 'audio' === $kind ) : ?><small>Solo WAV stereo · minimo 44.100 Hz / 16 bit. La durata deve coincidere con quella dichiarata, con tolleranza massima di 1 secondo.</small><?php endif; ?><button class="trb-button trb-button--compact" type="submit">Carica la sostituzione</button></form></details></div></article><?php endforeach; ?></div><?php $analysis_report = (array) get_post_meta( $release_id, '_trb_release_analysis_report', true ); if ( ! empty( $analysis_report['name'] ) && function_exists( 'trb_analysis_report_url' ) ) : ?><div class="trb-portal__message"><strong>Report di analisi</strong><p>Il controllo tecnico e dei diritti è documentato e collegato alla versione del WAV tramite hash SHA-256.</p><a class="trb-button trb-button--compact" href="<?php echo esc_url( trb_analysis_report_url( $release_id ) ); ?>">Scarica il report PDF</a></div><?php endif; ?><?php if ( function_exists( 'trb_resource_render_rights_box' ) ) trb_resource_render_rights_box( $release_id ); ?></div><?php
}

function trb_portal_release_pipeline_label( $release_id ) {
	$status = (string) get_post_meta( $release_id, '_trb_release_pipeline_status', true );
	$labels = array(
		'pending_pcloud_transfer'     => 'Trasferimento sicuro dei file in corso',
		'pcloud_transfer_waiting'     => 'Il trasferimento è temporaneamente in attesa. Non è necessario caricare nuovamente i file.',
		'archived_pending_analysis'   => 'File archiviati correttamente. Controllo del brano in attesa',
		'technical_analysis_running' => 'Analisi tecnica completa del WAV in corso',
		'technical_error'            => 'Il file richiede una correzione tecnica. Il WAV resta archiviato in sicurezza.',
		'technical_review'           => 'Analisi tecnica completata: verifica TRB necessaria',
		'copyright_queued'           => 'Controllo dei diritti in coda',
		'security_scan_waiting'      => 'I materiali sono conservati in sicurezza e attendono il controllo antivirus. Non caricarli nuovamente.',
		'security_rejected'          => 'Un materiale richiede verifica di sicurezza da parte di TRB.',
		'upload_failed'              => 'Dati acquisiti: caricamento dei file incompleto',
		'analysis_in_progress'        => 'Controllo del brano in corso',
		'analysis_waiting_configuration' => 'Il controllo del brano è temporaneamente in attesa. Non è necessario caricare nuovamente il file.',
		'ACR_BUDGET_LIMIT_REACHED'    => 'Il controllo del brano è temporaneamente in attesa. Non è necessario caricare nuovamente il file.',
		'PCLOUD_QUOTA_LIMIT_REACHED'  => 'Il trasferimento è temporaneamente in attesa. Non è necessario caricare nuovamente il file.',
		'copyright_documents_needed' => 'Documentazione sui diritti richiesta',
		'published_audio_conflict'   => 'Brano già pubblicato rilevato: pratica bloccata',
		'copyright_review'            => 'Verifica dei diritti in corso',
		'manual_review'               => 'Verifica manuale in corso',
		'approved'                    => 'Controllo completato',
	);
	return isset( $labels[ $status ] ) ? $labels[ $status ] : 'Dati contrattuali da completare';
}

function trb_portal_release_current_state_label( $release_id ) {
	$contract = (string) get_post_meta( $release_id, '_trb_contract_state', true );
	$labels = array(
		'preparing'              => 'Invio del contratto in corso',
		'contract_sent'          => 'Contratto inviato: firma richiesta',
		'signed'                 => 'Contratto firmato',
		'dispatch_error'         => 'Invio del contratto in verifica',
		'data_error'             => 'Dati contrattuali in verifica',
		'configuration_required' => 'Collegamento contrattuale in verifica',
	);
	if ( isset( $labels[ $contract ] ) ) return $labels[ $contract ];
	return trb_portal_release_pipeline_label( $release_id );
}

function trb_portal_render_release_section() {
	$releases  = trb_portal_user_releases();
	$profile   = trb_portal_user_profile();
	$types     = trb_portal_release_types();
	$genres    = trb_portal_genres();
	$roles     = trb_portal_contributor_roles();
	$status    = isset( $_GET['trb_release'] ) ? sanitize_key( wp_unslash( $_GET['trb_release'] ) ) : '';
	$complete  = trb_portal_artist_profile_is_complete();
	$today     = wp_date( 'Y-m-d' );
	$minimum_release_date = ( new DateTimeImmutable( 'today', wp_timezone() ) )->modify( '+30 days' )->format( 'Y-m-d' );
	$ddb12_limit_reached = trb_portal_ddb12_limit_reached();
	$ddb12_reset_label   = trb_portal_ddb12_next_reset_label();
	?>
	<section id="release" class="trb-portal__section trb-portal__section--releases">
		<div class="trb-portal__section-heading"><p class="trb-portal__eyebrow">PUBBLICAZIONI</p><h2>Le tue release</h2><p>Inserisci metadati, crediti e file audio della pubblicazione, quindi ricevi il contratto da sottoscrivere per avviare l’iter di distribuzione.</p></div>
		<?php if ( 'created' === $status ) : ?><div class="trb-portal__message trb-portal__message--success">Pratica creata correttamente.</div><?php endif; ?>
		<?php if ( 'file_replaced' === $status ) : ?><div class="trb-portal__message trb-portal__message--success">Nuovo file acquisito. Il precedente verrà rimosso automaticamente soltanto dopo il trasferimento verificato su pCloud.</div><?php endif; ?>
		<?php if ( 'rights_uploaded' === $status ) : ?><div class="trb-portal__message trb-portal__message--success">Documento acquisito e archiviato con il brano. La verifica prosegue automaticamente.</div><?php endif; ?>
		<?php if ( 'rights_waiting' === $status ) : ?><div class="trb-portal__message"><strong>Documento acquisito.</strong><p>Il trasferimento è temporaneamente in attesa. Non è necessario caricarlo nuovamente.</p></div><?php endif; ?>
		<?php if ( 'rights_invalid' === $status || 'rights_error' === $status ) : ?><div class="trb-portal__message trb-portal__message--error">Il documento non è stato acquisito. Sono ammessi PDF, JPG, PNG o DOCX fino a 20 MB.</div><?php endif; ?>
		<?php if ( 'profile_required' === $status ) : ?><div class="trb-portal__message trb-portal__message--error">Completa prima il profilo artista.</div><?php endif; ?>
		<?php if ( 'duration_mismatch' === $status ) : ?><div class="trb-portal__message trb-portal__message--error"><strong>La durata indicata non coincide con il file WAV.</strong><p>Correggi minuti e secondi del brano: è ammessa una tolleranza massima di 1 secondo rispetto alla durata reale del file.</p></div><?php endif; ?>
		<?php if ( 'file_invalid' === $status ) : ?><div class="trb-portal__message trb-portal__message--error"><strong>Il file sostitutivo non è stato acquisito.</strong><p>Formato, dimensioni o caratteristiche tecniche non rispettano i requisiti indicati. Il file precedente è rimasto invariato.</p></div><?php endif; ?>
		<?php if ( 'file_error' === $status ) : ?><div class="trb-portal__message trb-portal__message--error"><strong>La sostituzione non è stata completata.</strong><p>Il file precedente è rimasto invariato. Controlla la connessione e riprova una sola volta.</p></div><?php endif; ?>
		<?php if ( 'monthly_limit' === $status ) : ?><div class="trb-portal__message trb-portal__message--error"><strong>Raggiunto limite mensile di release distribuibili</strong><p>Il profilo DDB12 consente di avviare una sola pratica per ogni mese solare, indipendentemente dal tipo di pubblicazione: singolo, EP, album, doppio album, compilation, collection o catalogo. Il limite si rinnova automaticamente il primo giorno di ogni mese; potrai creare una nuova release dal <?php echo esc_html( $ddb12_reset_label ); ?>, per un massimo complessivo di 12 release nell’anno.</p></div><?php endif; ?>
		<?php if ( 'upload_in_progress' === $status ) : ?><div class="trb-portal__message"><strong>Caricamento già in elaborazione</strong><p>La richiesta precedente è ancora in corso. Non inviare nuovamente i file: la pagina si aggiornerà al completamento.</p></div><?php endif; ?>
		<?php if ( 'single_title_mismatch' === $status ) : ?><div class="trb-portal__message trb-portal__message--error"><strong>I titoli non coincidono.</strong><p>Per una pubblicazione di tipo Singolo, il titolo della release deve essere identico al titolo del brano, comprese maiuscole, accenti e punteggiatura.</p></div><?php endif; ?>
		<?php if ( 'upload_failed' === $status ) : ?><div class="trb-portal__message trb-portal__message--error"><strong>Caricamento incompleto.</strong><p>I dati della pratica sono stati conservati, ma uno o più file devono essere verificati o sostituiti.</p></div><?php endif; ?>
