				<label class="trb-track-featuring">Featuring <small>solo se presente</small><input type="text" name="trb_tracks[__INDEX__][featuring]" maxlength="160" /></label>
				<label class="trb-track-advisory">Parental Advisory <span aria-hidden="true">*</span><select name="trb_tracks[__INDEX__][advisory]" required data-track-advisory><option value="" selected disabled>Seleziona una voce</option><option value="no_lyrics">Nessun testo</option><option value="non_explicit">Testo non esplicito</option><option value="clean">Clean (versione censurata)</option><option value="explicit">Testo con contenuti espliciti</option></select></label>
				<label class="trb-track-duration">Durata <span aria-hidden="true">*</span><span class="trb-duration-picker"><select name="trb_tracks[__INDEX__][duration_minutes]" required aria-label="Minuti"><option value="">Minuti</option><?php for ( $minute = 0; $minute <= 19; $minute++ ) : ?><option value="<?php echo esc_attr( $minute ); ?>"><?php echo esc_html( sprintf( '%02d min', $minute ) ); ?></option><?php endfor; ?></select><select name="trb_tracks[__INDEX__][duration_seconds]" required aria-label="Secondi"><option value="">Secondi</option><?php for ( $second = 0; $second <= 59; $second++ ) : ?><option value="<?php echo esc_attr( $second ); ?>"><?php echo esc_html( sprintf( '%02d sec', $second ) ); ?></option><?php endfor; ?></select></span></label>
				<label class="trb-track-existing-isrc" data-existing-isrc hidden><span data-isrc-title>ISRC del brano già pubblicato</span> <span aria-hidden="true">*</span><input type="text" name="trb_existing_isrc[__INDEX__]" minlength="12" maxlength="12" pattern="[A-Z]{2}[A-Z0-9]{3}[0-9]{7}" inputmode="latin" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="Es. ITV242600005" disabled /><small data-isrc-help>Inserisci i 12 caratteri dell’ISRC, senza spazi o trattini.</small></label>
				<label class="trb-track-primary-genre">Genere musicale primario <span aria-hidden="true">*</span><input type="search" name="trb_tracks[__INDEX__][primary_genre]" required list="trb-release-genres" autocomplete="off" placeholder="Cerca e seleziona il genere primario" /></label>
				<label class="trb-track-secondary-genre">Genere musicale secondario <small>facoltativo</small><input type="search" name="trb_tracks[__INDEX__][secondary_genre]" list="trb-release-genres" autocomplete="off" placeholder="Cerca un eventuale genere secondario" /></label>
				<label class="trb-track-content-nature">Natura del contenuto <span aria-hidden="true">*</span><select name="trb_tracks[__INDEX__][content_nature]" required data-content-nature><option value="" selected disabled>Seleziona una voce</option><option value="original">Opera originale</option><option value="type_beat">Type beat / beat con licenza</option><option value="remix">Remix di un brano edito con licenza</option><option value="protected_samples">Contiene estratti da film o da altri brani protetti da copyright</option></select><small class="trb-rights-policy-note">Le cover e le reinterpretazioni non sono accettate da TRB rec.</small></label>
				<label class="trb-track-rights-basis">Titolarità e autorizzazioni <span aria-hidden="true">*</span><select name="trb_tracks[__INDEX__][rights_basis]" required data-rights-basis disabled><option value="">Seleziona prima la natura</option></select><small data-rights-help>La dichiarazione determina i controlli e la documentazione richiesta.</small></label>
				<label class="trb-rights-document" data-rights-document hidden>Licenza o autorizzazione specifica <span aria-hidden="true">*</span><input type="file" name="trb_track_rights_document[__INDEX__]" accept=".pdf,application/pdf" disabled /><small>Allega un unico PDF completo, massimo 10 MB. Se non disponi della licenza necessaria, il brano non può essere inviato né pubblicato.</small></label>
			</div><div class="trb-track-audio"><strong>File audio del brano <span>*</span></strong><input type="file" name="trb_track_audio[__INDEX__]" accept=".wav,audio/wav,audio/x-wav" required /><small>Solo formato WAV · minimo 44.100 Hz / 16 bit. È fortemente consigliato 48.000 Hz / 24 bit. Il sistema verifica automaticamente caratteristiche e durata reale del file.</small><span class="trb-audio-duration-check" data-audio-duration-check aria-live="polite"></span><?php if ( 'dds' === $profile ) : ?><input type="hidden" name="trb_tracks[__INDEX__][audio_status]" value="mastered" /><p class="trb-audio-dds-note">Per il profilo DDS il file audio deve essere già in versione master.</p><?php else : ?><fieldset class="trb-audio-status"><legend>Stato del file audio <span>*</span></legend><label><input type="radio" name="trb_tracks[__INDEX__][audio_status]" value="mastered" required /> Il brano è già in versione master</label><label><input type="radio" name="trb_tracks[__INDEX__][audio_status]" value="mastering" required /> Richiedo il mastering del brano</label></fieldset><?php endif; ?></div><label class="trb-track-lyrics" data-track-lyrics hidden>Testo del brano <span>*</span><input type="file" name="trb_track_lyrics[__INDEX__]" accept=".txt,.docx,.odt,.rtf,text/plain,application/rtf,text/rtf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.oasis.opendocument.text" disabled /><small>Obbligatorio quando il brano contiene un testo. Allega TXT, DOCX, ODT o RTF · massimo 5 MB.</small></label></div>
			<fieldset class="trb-portal__credits"><legend>Crediti</legend><p class="trb-portal__field-help">Inserisci ogni persona separatamente e seleziona tutti i ruoli che si applicano.</p>
				<div class="trb-contributor-group" data-contributor-group="writers"><h4>Autori e compositori <span>*</span></h4><p>Indica chi ha scritto il testo e chi ha composto la musica. La quota viene ripartita automaticamente in parti uguali fra le persone inserite.</p><div data-contributor-rows><div class="trb-contributor-row trb-contributor-row--writer"><input type="text" name="trb_tracks[__INDEX__][credits][writers][0][name]" required aria-label="Nome dell’autore o compositore" placeholder="Nome completo" /><fieldset class="trb-writer-roles"><legend>Ruolo <span>*</span></legend><label><input type="checkbox" name="trb_tracks[__INDEX__][credits][writers][0][roles][]" value="Lyricist" /> Autore</label><label><input type="checkbox" name="trb_tracks[__INDEX__][credits][writers][0][roles][]" value="Composer" /> Compositore</label></fieldset><label class="trb-writer-share">Quota diritto d’autore<input type="text" name="trb_tracks[__INDEX__][credits][writers][0][share]" value="100,00%" readonly tabindex="-1" data-writer-share /></label><button type="button" data-remove-contributor hidden>Rimuovi</button></div></div><button type="button" class="trb-add-contributor" data-add-contributor>+ Aggiungi autore/compositore</button></div>
				<div class="trb-contributor-group" data-contributor-group="credits"><h4>Crediti <span>*</span></h4><p>Inserisci ogni ulteriore partecipante al brano e seleziona il ruolo Too Lost corrispondente. Aggiungi una riga distinta per ciascuna persona e per ciascun ruolo.</p><div data-contributor-rows><div class="trb-contributor-row"><input type="text" name="trb_tracks[__INDEX__][credits][credits][0][name]" required aria-label="Nome della persona accreditata" placeholder="Nome completo o nome d’arte" /><input type="search" name="trb_tracks[__INDEX__][credits][credits][0][role]" required aria-label="Ruolo nei crediti" list="trb-credit-roles" autocomplete="off" placeholder="Cerca ruolo" /><button type="button" data-remove-contributor hidden>Rimuovi</button></div></div><button type="button" class="trb-add-contributor" data-add-contributor>+ Aggiungi credito</button></div>
			</fieldset>
		</article>
	</template>
	<datalist id="trb-release-genres"><?php foreach ( $genres as $genre ) : ?><option value="<?php echo esc_attr( $genre ); ?>"><?php echo esc_html( $genre ); ?></option><?php endforeach; ?></datalist>
	<datalist id="trb-credit-roles"><?php foreach ( array_keys( $roles['credits'] ) as $role ) : ?><option value="<?php echo esc_attr( $role ); ?>"><?php echo esc_html( $role ); ?></option><?php endforeach; ?></datalist>
	<script>
	(function(){
		var form=document.querySelector('[data-release-form]'); if(!form)return;
		var wrap=form.querySelector('[data-tracks]'), template=document.getElementById('trb-portal-track-template'), add=form.querySelector('[data-add-track]'), title=form.querySelector('.trb-portal__release-title'), releaseDate=form.querySelector('.trb-portal__release-date'), releaseDateInput=releaseDate.querySelector('input'), originalDate=form.querySelector('.trb-portal__original-date'), originalDateInput=originalDate.querySelector('input'), autoAssignIsrc=<?php echo wp_json_encode( 'trb' === $profile ); ?>;
		function contributorRows(group){var rows=group.querySelector('[data-contributor-rows]');return rows?rows.querySelectorAll(':scope > .trb-contributor-row:not([data-shadow])'):[];}
		function contributorPrototype(group){var source=template.content.querySelector('[data-contributor-group="'+group.dataset.contributorGroup+'"] [data-contributor-rows] > .trb-contributor-row');return source?source.cloneNode(true):null;}
		function validateGenres(track){var primary=track.querySelector('[name$="[primary_genre]"]'),secondary=track.querySelector('[name$="[secondary_genre]"]'),same=primary.value.trim()!==''&&primary.value.trim()===secondary.value.trim();secondary.setCustomValidity(same?'Il genere secondario deve essere diverso dal genere primario.':'');}
		function normalizeIsrc(input){var clean=String(input.value||'').toUpperCase().replace(/[^A-Z0-9]/g,'');if(input.value!==clean)input.value=clean;input.setCustomValidity(clean&& !/^[A-Z]{2}[A-Z0-9]{3}[0-9]{7}$/.test(clean)?'Inserisci un ISRC valido di 12 caratteri.':'');}
		function updateLyrics(track){var advisory=track.querySelector('[data-track-advisory]'),wrap=track.querySelector('[data-track-lyrics]'),file=wrap.querySelector('input[type="file"]'),required=advisory.value!==''&&advisory.value!=='no_lyrics';wrap.hidden=!required;file.disabled=!required;file.required=required;if(!required)file.value='';}
		function syncRightsFields(track){var nature=track.querySelector('[data-content-nature]'),basis=track.querySelector('[data-rights-basis]'),documentWrap=track.querySelector('[data-rights-document]');if(!nature||!basis||!documentWrap)return;var documentInput=documentWrap.querySelector('input'),needsDocument=nature.value==='type_beat'||nature.value==='protected_samples'||(nature.value==='remix'&&basis.value==='licensed');documentWrap.hidden=!needsDocument;documentInput.disabled=!needsDocument;documentInput.required=needsDocument;if(!needsDocument)documentInput.value='';}
		function updateRights(track){var nature=track.querySelector('[data-content-nature]'),basis=track.querySelector('[data-rights-basis]'),help=track.querySelector('[data-rights-help]'),choices={original:[['owned','L\'opera è originale e non include contenuti di terzi']],type_beat:[['exclusive','Dispongo di una licenza esclusiva'],['nonexclusive','Dispongo di una licenza non esclusiva / basic']],remix:[['licensed','Dispongo della specifica licenza per distribuire il remix']],protected_samples:[['licensed','Dispongo di licenze specifiche per tutti i contenuti protetti']]};basis.innerHTML='';(choices[nature.value]||[]).forEach(function(item){var option=document.createElement('option');option.value=item[0];option.textContent=item[1];basis.appendChild(option);});basis.disabled=!choices[nature.value];if(choices[nature.value]){var first=document.createElement('option');first.value='';first.textContent='Seleziona una dichiarazione';first.disabled=true;first.selected=true;basis.insertBefore(first,basis.firstChild);}var helps={original:'Seleziona questa voce solo se il brano non utilizza opere, master o contenuti protetti appartenenti a terzi.',type_beat:'La licenza del beat è obbligatoria. Le licenze non esclusive possono escludere Content ID e monetizzazione social.',remix:'Per inviare il remix devi allegare la licenza specifica che ne autorizza la distribuzione.',protected_samples:'Questa voce riguarda estratti da film o altri brani protetti da copyright. Senza licenze specifiche il brano non può essere inviato.'};help.textContent=helps[nature.value]||'La dichiarazione determina i controlli e la documentazione richiesta.';syncRightsFields(track);}
		function updateWriterShares(group){var rows=contributorRows(group),count=rows.length,base=Math.floor(10000/count),remainder=10000-(base*count);rows.forEach(function(row,index){var share=row.querySelector('[data-writer-share]'),roles=row.querySelectorAll('.trb-writer-roles input[type="checkbox"]'),selected=Array.prototype.some.call(roles,function(role){return role.checked;});if(share){var cents=base+(index<remainder?1:0);share.value=(cents/100).toFixed(2).replace('.',',')+'%';}if(roles.length)roles[0].setCustomValidity(selected?'':'Seleziona Autore, Compositore oppure entrambi.');});}
		function renumberContributors(track){track.querySelectorAll('[data-contributor-group]').forEach(function(group){var key=group.dataset.contributorGroup; contributorRows(group).forEach(function(row,index){row.querySelectorAll('[name]').forEach(function(field){field.name=field.name.replace(new RegExp('(credits\\]\\['+key+'\\]\\[)\\d+(\\])'),'$1'+index+'$2');}); var remove=row.querySelector('[data-remove-contributor]'); if(remove)remove.hidden=contributorRows(group).length===1;});if(key==='writers')updateWriterShares(group);});}
		function renumber(){var tracks=wrap.querySelectorAll('[data-track]');tracks.forEach(function(track,index){track.querySelector('[data-track-number]').textContent=index+1;track.querySelectorAll('[name]').forEach(function(field){field.name=field.name.replace(/trb_tracks\[\d+\]/,'trb_tracks['+index+']').replace(/trb_track_lyrics\[\d+\]/,'trb_track_lyrics['+index+']').replace(/trb_track_audio\[\d+\]/,'trb_track_audio['+index+']').replace(/trb_track_rights_document\[\d+\]/,'trb_track_rights_document['+index+']').replace(/trb_existing_isrc\[\d+\]/,'trb_existing_isrc['+index+']');});renumberContributors(track);track.querySelector('[data-remove-track]').hidden=tracks.length===1;});var selected=form.querySelector('input[name="trb_release_type"]:checked');if(selected){var max=Number(selected.dataset.max||60);add.disabled=tracks.length>=max;add.textContent=tracks.length>=max?'Limite raggiunto':'+ Aggiungi un altro brano';}}
		function addTrack(){var index=wrap.querySelectorAll('[data-track]').length,html=template.innerHTML.replace(/__INDEX__/g,index);wrap.insertAdjacentHTML('beforeend',html);var track=wrap.lastElementChild,primary=track.querySelector('[name$="[primary_genre]"]'),secondary=track.querySelector('[name$="[secondary_genre]"]'),advisory=track.querySelector('[data-track-advisory]'),nature=track.querySelector('[data-content-nature]'),basis=track.querySelector('[data-rights-basis]'),isrc=track.querySelector('[data-existing-isrc] input');primary.addEventListener('input',function(){validateGenres(track);});secondary.addEventListener('input',function(){validateGenres(track);});advisory.addEventListener('change',function(){updateLyrics(track);});nature.addEventListener('change',function(){updateRights(track);});basis.addEventListener('change',function(){syncRightsFields(track);});if(isrc)isrc.addEventListener('input',function(){normalizeIsrc(isrc);});updateLyrics(track);updateRights(track);renumber();updateState();}
		function updateType(){var selected=form.querySelector('input[name="trb_release_type"]:checked'),catalogue=selected&&selected.dataset.catalogue==='1';title.hidden=!!catalogue;title.querySelector('input').required=!catalogue;if(catalogue){title.querySelector('input').value='';var old=form.querySelector('input[value="previously_released"]');old.checked=true;}updateState();renumber();}
		function updateState(){var selected=form.querySelector('input[name="trb_release_state"]:checked'),unreleased=selected&&selected.value==='unreleased',old=selected&&selected.value==='previously_released';releaseDate.hidden=!unreleased;releaseDateInput.required=!!unreleased;releaseDateInput.disabled=!unreleased;if(!unreleased)releaseDateInput.value='';originalDate.hidden=!old;originalDateInput.required=!!old;originalDateInput.disabled=!old;if(!old)originalDateInput.value='';wrap.querySelectorAll('[data-existing-isrc]').forEach(function(label){var input=label.querySelector('input'),heading=label.querySelector('[data-isrc-title]'),help=label.querySelector('[data-isrc-help]'),automatic=!!unreleased&&autoAssignIsrc;label.hidden=!old&&!automatic;input.disabled=!old;input.required=!!old;input.readOnly=!old;if(old){heading.textContent='ISRC del brano già pubblicato';help.textContent='Inserisci i 12 caratteri dell’ISRC, senza spazi o trattini.';input.placeholder='Es. ITV242600005';normalizeIsrc(input);}else{input.value='';input.setCustomValidity('');heading.textContent='Codice ISRC assegnato';help.textContent='L’ISRC a 12 caratteri verrà assegnato dal sistema soltanto dopo l’invio riuscito del modulo e non sarà modificabile.';input.placeholder='Assegnato automaticamente dopo l’invio';}});}
		add.addEventListener('click',addTrack);
		wrap.addEventListener('click',function(event){var target=event.target;if(target.matches('[data-remove-track]')){target.closest('[data-track]').remove();renumber();return;}if(target.matches('[data-add-contributor]')){var group=target.closest('[data-contributor-group]'),rows=group.querySelector('[data-contributor-rows]'),track=target.closest('[data-track]'),clone=contributorPrototype(group);if(!clone)return;var trackIndex=Array.prototype.indexOf.call(wrap.querySelectorAll('[data-track]'),track);clone.querySelectorAll('[name]').forEach(function(field){field.name=field.name.replace(/__INDEX__/g,trackIndex);});clone.querySelectorAll('input').forEach(function(input){if(input.type==='checkbox')input.checked=false;else input.value='';});rows.appendChild(clone);renumberContributors(track);return;}if(target.matches('[data-remove-contributor]')){var group=target.closest('[data-contributor-group]');if(contributorRows(group).length<=1)return;target.closest('.trb-contributor-row').remove();renumberContributors(group.closest('[data-track]'));}});
		wrap.addEventListener('change',function(event){if(event.target.matches('.trb-writer-roles input[type="checkbox"]'))updateWriterShares(event.target.closest('[data-contributor-group]'));});
		form.querySelectorAll('input[name="trb_release_type"]').forEach(function(input){input.addEventListener('change',updateType);});
		form.querySelectorAll('input[name="trb_release_state"]').forEach(function(input){input.addEventListener('change',updateState);});
		form.addEventListener('submit',function(event){if(!form.checkValidity())return;event.preventDefault();if(form.dataset.submitting==='1')return;form.dataset.submitting='1';var button=form.querySelector('.trb-button--submit-release'),box=form.querySelector('[data-release-upload-progress]'),bar=box.querySelector('[data-release-upload-bar]'),value=box.querySelector('[data-release-upload-value]'),text=box.querySelector('[data-release-upload-text]'),xhr=new XMLHttpRequest();button.disabled=true;button.textContent='Caricamento in corso…';box.hidden=false;xhr.open('POST',form.action,true);xhr.upload.addEventListener('progress',function(e){if(!e.lengthComputable)return;var percent=Math.min(99,Math.round(e.loaded/e.total*100));bar.value=percent;value.textContent=percent+'%';text.textContent=percent<100?'Trasferimento dei file…':'Verifica e registrazione della pratica…';});xhr.addEventListener('load',function(){bar.value=100;value.textContent='100%';if(xhr.responseURL){window.location.assign(xhr.responseURL);return;}form.dataset.submitting='0';button.disabled=false;button.textContent='Crea la pratica release';text.textContent='Il server non ha completato la richiesta. I file non sono stati duplicati: riprova una sola volta.';});xhr.addEventListener('error',function(){form.dataset.submitting='0';button.disabled=false;button.textContent='Crea la pratica release';text.textContent='Connessione interrotta. Controlla la rete prima di riprovare.';});xhr.send(new FormData(form));});
		addTrack(); updateState();
	}());
	</script>
<?php
}

function trb_portal_redirect_artist_after_login( $redirect_to, $requested_redirect_to, $user ) {
	if ( $user instanceof WP_User && ! $user->has_cap( 'manage_options' ) ) {
		return home_url( '/area-artisti/' );
	}

	return $redirect_to;
}
add_filter( 'login_redirect', 'trb_portal_redirect_artist_after_login', 9999, 3 );

/**
 * LoginWP can replace the WordPress login_redirect value with an old
 * contract-specific destination. This runs after authentication and ends the
 * browser request for contractual artists, so the legacy rule cannot win.
 */
function trb_portal_force_artist_dashboard_after_login( $user_login, $user ) {
	if ( ! ( $user instanceof WP_User ) || $user->has_cap( 'manage_options' ) || wp_doing_ajax() || ( defined( 'REST_REQUEST' ) && REST_REQUEST ) ) {
		return;
	}

	wp_safe_redirect( home_url( '/area-artisti/' ) );
	exit;
}
add_action( 'wp_login', 'trb_portal_force_artist_dashboard_after_login', 9999, 2 );

/**
 * Safety net for legacy role home pages.
 *
 * Some existing accounts authenticate through Profile Builder/LoginWP rules
 * that issue their redirect before WordPress' normal login_redirect filter can
 * take precedence. Do not leave those artists in the old FAQ homes: whenever
 * one of the retired contract-specific home pages is reached, send the signed
 * in contractual artist to the single new dashboard instead. Documentation,
 * demo forms and the rest of the site are deliberately not affected.
 */
function trb_portal_redirect_legacy_artist_home() {
	if ( ! is_user_logged_in() || current_user_can( 'manage_options' ) ) {
		return;
	}

	$legacy_homes = array(
		'homepage-dds',
		'homepage-ddb',
		'homepage-ddb-trb',
		'homepage-trb',
		'homepage-trb-basic',
		'home-page-dds',
		'home-page-ddb',
		'home-page-ddb-trb',
		'home-page-trb',
		'home-page-trb-basic',
	);

	// A few older login flows fall back to the site's front page rather than a
	// named role page. For contractual artists the front page is legacy too.
	if ( is_front_page() || is_page( $legacy_homes ) || is_404() ) {
		wp_safe_redirect( home_url( '/area-artisti/' ) );
		exit;
	}
}
add_action( 'template_redirect', 'trb_portal_redirect_legacy_artist_home', 0 );

/** Signed-in users should never land on authentication or registration forms. */
function trb_portal_redirect_authenticated_entry_pages() {
	if ( is_admin() || ! is_user_logged_in() || ! is_page( array( 'accedi', 'registrati', 'recupera-password' ) ) ) return;
	wp_safe_redirect( current_user_can( 'manage_options' ) ? admin_url() : home_url( '/area-artisti/' ), 302 );
	exit;
}
