	$scripts = array( 'wpdm-modal', 'wpdm-frontend-js', 'wpdm-frontjs', 'eazydocs-assistant', 'eazydocs-subscription', 'bootstrap', 'wow', 'imagesloaded', 'masonry', 'docy-main', 'docy-ajax-search-form' );

